def supa_headers():
    return {
        "apikey": SUPABASE_KEY,
        "Authorization": f"Bearer {SUPABASE_KEY}",
        "Content-Type": "application/json",
        "Prefer": "resolution=merge-duplicates"
    }

def verify_signature(payload_bytes, signature_header):
    if not APP_SECRET:
        return False
    if not signature_header or not signature_header.startswith("sha256="):
        return False
    expected_sig = hmac.new(APP_SECRET.encode('utf-8'), payload_bytes, hashlib.sha256).hexdigest()
    given_sig = signature_header.split("sha256=")[1]
    return hmac.compare_digest(expected_sig, given_sig)

def rebuild_kb_index():
    raw = cache.get("kb", DEFAULT_KB) or []
    by_cid = {}
    if isinstance(raw, list):
        for item in raw:
            if isinstance(item, dict):
                cid = item.get("client_id") or "client_default"
                by_cid.setdefault(cid, []).append(item)
    cache["kb_by_cid"] = by_cid

def rebuild_rules_index():
    raw = cache.get("rules", DEFAULT_RULES) or []
    by_cid = {}
    if isinstance(raw, list):
        for item in raw:
            if isinstance(item, dict):
                cid = item.get("client_id") or "client_default"
                by_cid.setdefault(cid, []).append(item)
    cache["rules_by_cid"] = by_cid

def sync_from_supabase():
    global AGENCY_CLIENTS_STORE, ACCOUNTS_STORE
    if SUPABASE_URL and SUPABASE_KEY:
        try:
            url = f"{SUPABASE_URL}/rest/v1/app_settings?select=key,value"
            r = requests.get(url, headers=supa_headers(), timeout=4)
            if r.status_code == 200:
                for row in r.json():
                    k, v = row.get("key"), row.get("value")
                    if not k or not v:
                        continue
                    try:
                        parsed = json.loads(v)
                        if isinstance(parsed, str):
                            try: parsed = json.loads(parsed)
                            except: pass
                    except:
                        parsed = v
                    if k == "meta_ai_kb":
                        cache["kb"] = parsed
                    elif k == "meta_ai_rules":
                        cache["rules"] = parsed
                    elif k == "meta_ai_accounts" and isinstance(parsed, list) and parsed:
                        ACCOUNTS_STORE[:] = parsed
                        cache["accounts"] = parsed
                    elif k == "meta_ai_clients" and isinstance(parsed, list) and parsed:
                        AGENCY_CLIENTS_STORE[:] = parsed
                        cache["clients"] = parsed
                    elif k == "meta_ai_bot_enabled":
                        cache["bot_enabled"] = bool(parsed)
                    elif k == "meta_ai_approval_mode":
                        cache["approval_mode"] = str(parsed) if parsed else "auto"
                    elif k == "meta_ai_scheduled_posts":
                        cache["scheduled_posts"] = parsed if isinstance(parsed, list) else []
                    elif k == "meta_ai_customer_styles":
                        cache["customer_styles"] = parsed if isinstance(parsed, dict) else {}
                    elif k == "meta_ai_system_prompt":
                        cache["prompt"] = parsed  # global/default base prompt
                    elif k.startswith("meta_ai_system_prompt::"):
                        _pcid = k.split("::", 1)[1]
                        cache.setdefault("prompts", {})[_pcid] = parsed  # per-client brand prompt
                    elif k == "meta_ai_client_modes" and isinstance(parsed, dict):
                        cache["client_modes"] = parsed  # per-client auto/manual reply mode
                    elif k == "meta_ai_users":
                        try:
                            # NEVER overwrite the env-derived admin account — its password
                            # comes from ADMIN_PASS and must stay authoritative, else a stale
                            # stored admin hash would lock the real admin out.
                            _admin_un = os.environ.get("ADMIN_USER") or "admin"
                            _items = parsed.items() if isinstance(parsed, dict) else \
                                     [(u.get("username"), u) for u in parsed if isinstance(u, dict)]
                            for _un, _rec in _items:
                                if _un == _admin_un:
                                    continue
                                if isinstance(_rec, dict) and _rec.get("password"):
                                    USERS_DB[_un] = _rec
                            cache["users"] = USERS_DB
                        except Exception:
                            pass
                    elif k == "meta_ai_email_logs" and isinstance(parsed, list):
                        cache["email_logs"] = parsed
                    elif k == "meta_ai_smtp_config" and isinstance(parsed, dict):
                        cache["smtp_config"] = parsed
                    elif k == "meta_ai_employees" and isinstance(parsed, list):
                        cache["employees"] = parsed
                    elif k == "meta_ai_tasks" and isinstance(parsed, list):
                        cache["tasks"] = parsed
                    elif k == "meta_ai_task_logs" and isinstance(parsed, list):
                        cache["task_logs"] = parsed
                    elif k == "meta_ai_project_teams" and isinstance(parsed, dict):
                        cache["project_teams"] = parsed
                    elif k == "meta_ai_client_strategies" and isinstance(parsed, dict):
                        cache["client_strategies"] = parsed
        except Exception as e:
            print(f"[Supabase Sync Exception] {e}")
    rebuild_kb_index()
    rebuild_rules_index()

def push_setting(key, value):
    # SAFETY: never overwrite the accounts/clients lists with an empty value — an empty
    # store almost always means "this serverless instance hasn't synced yet", and writing
    # it would wipe real connected accounts/clients from persistence.
    if key in ("meta_ai_accounts", "meta_ai_clients") and (not value or not isinstance(value, list)):
        print(f"[Supabase Push BLOCKED] refusing to overwrite {key} with empty value")
        return
    if SUPABASE_URL and SUPABASE_KEY:
        try:
            url = f"{SUPABASE_URL}/rest/v1/app_settings"
            val_str = json.dumps(value, ensure_ascii=False) if isinstance(value, (dict, list)) else str(value)
            res = requests.post(url, headers=supa_headers(), json={"key": key, "value": val_str}, timeout=5)
            print(f"[Supabase Push] {key} -> HTTP {res.status_code}")
        except Exception as e:
            print(f"[Supabase Push Exception] {key}: {e}")

