def generate_embedding(text):
    if OPENROUTER_API_KEY:
        try:
            import requests
            res = requests.post(
                "https://openrouter.ai/api/v1/embeddings",
                headers={"Authorization": f"Bearer {OPENROUTER_API_KEY}", "Content-Type": "application/json"},
                json={"model": "openai/text-embedding-3-small", "input": text},
                timeout=10
            )
            if res.status_code == 200:
                return res.json()["data"][0]["embedding"]
        except Exception as e:
            print(f"[Embedding Error] {e}")
    return None

def search_kb(query, client_id=None):
    cid = client_id or current_client_id()
    items = get_kb_data()
    if not items or not query or not str(query).strip():
        return ""
        
    # 1. Try vector RAG on Supabase if possible
    embedding = generate_embedding(query)
    if embedding and SUPABASE_URL and SUPABASE_KEY:
        try:
            import requests
            res = requests.post(
                f"{SUPABASE_URL}/rest/v1/rpc/match_documents",
                headers=supa_headers(),
                json={
                    "query_embedding": embedding,
                    "match_threshold": 0.7,
                    "match_count": 3,
                    "p_client_id": cid
                },
                timeout=10
            )
            if res.status_code == 200:
                docs = res.json()
                if docs:
                    return "\n".join([doc.get("content", "") for doc in docs])
        except Exception as e:
            print(f"[Vector Search Error] {e}")

    # 2. Fallback to keyword search
    client_items = [i for i in items if (i.get("client_id") or "client_default") == cid]
    words = [w for w in re.split(r'\s+', str(query).lower()) if len(w) >= 2]
    scored = []
    for item in client_items:
        text = (item.get("question", "") + " " + item.get("answer", "")).lower()
        score = sum(1 for w in words if w in text)
        if score > 0:
            scored.append((score, item))
    scored.sort(key=lambda x: x[0], reverse=True)
    if not scored:
        return ""
    res_lines = []
    for _, i in scored[:2]:
        res_lines.append("- " + str(i.get('question')) + ": " + str(i.get('answer')))
    return "\n".join(res_lines)

def check_custom_rules(message, client_id=None, post_url_or_id=None):
    cid = client_id or current_client_id()
    rules = get_rules_data()
    if not rules or not message or not isinstance(message, str):
        return None
    msg_lower = message.lower().strip()
    target_post = str(post_url_or_id or "").strip().lower()
    
    for rule in rules:
        if not rule.get("is_active", True):
            continue
        r_cid = rule.get("client_id") or "client_default"
        if r_cid != cid:
            continue
        
        # Check Post-Specific Rule Filter (if rule is tied to a specific post URL or ID)
        rule_post = str(rule.get("post_url") or rule.get("post_id") or "").strip().lower()
        if rule_post:
            if not target_post:
                continue
            if rule_post not in target_post and target_post not in rule_post:
                continue

        trigger = (rule.get("trigger") or "").lower().strip()
        if not trigger or trigger == "*":
            if rule_post and (rule_post in target_post or target_post in rule_post):
                return rule
            continue

        match_type = rule.get("match_type", "contains")
        if match_type == "exact" and msg_lower == trigger:
            return rule
        elif match_type == "contains" and trigger in msg_lower:
            return rule
        elif match_type == "startswith" and msg_lower.startswith(trigger):
            return rule
    return None

