conv_cache = {"ttl": 15}
_ig_pull_debug = {}

@app.route("/api/conversations", methods=["GET"])
def api_conversations():
    force = request.args.get("force") == "true"
    now = time.time()
    all_threads = []
    cid = current_client_id()
    cc = conv_cache.setdefault(cid, {"timestamp": 0, "data": None, "all_threads": []})
    
    if not force and cc.get("all_threads") and (now - cc["timestamp"] < conv_cache["ttl"]):
        all_threads = cc["all_threads"]
    else:
        sync_from_supabase()
    
    # Get active client tokens
    client_accounts = [a for a in ACCOUNTS_STORE if a.get("client_id") == cid]

    # Optional: filter the inbox to a single connected account (header account switcher)
    filter_account_id = request.args.get("account_id", "").strip()
    if filter_account_id:
        only = [a for a in client_accounts if str(a.get("id")) == filter_account_id or str(a.get("ig_id")) == filter_account_id]
        if only:
            client_accounts = only
    all_threads = []

    # Build the full list of pages to pull from (all pages the token can see + attached accounts),
    # so the inbox shows conversations from EVERY connected page — not just the first one.
    # Build the pages to pull STRICTLY from the ACTIVE CLIENT's own connected pages,
    # using each page's stored page token. Never fall back to the default Domya page —
    # that was the bug that made every client show Domya's messages.
    pages_to_pull = []
    _seen_pids = set()
    def _add_page(pid, ptok, igid, igtok):
        pid = str(pid or "")
        if not pid or not ptok or pid in _seen_pids:
            return
        _seen_pids.add(pid)
        pages_to_pull.append({"fb_page_id": pid, "fb_token": ptok, "ig_id": str(igid or ""), "ig_token": igtok or ptok})
    for _a in client_accounts:
        if _a.get("platform") == "facebook":
            _t = decrypt(_a["access_token_enc"]) if _a.get("access_token_enc") else _a.get("access_token")
            if not (_t and len(_t) > 20):
                continue
            _pid = str(_a.get("id"))
            _igid = _a.get("ig_id")
            # Resolve THIS page's own fully-scoped page token. The stored token can be an
            # old/limited page token that reads posts but NOT comments — so we re-resolve
            # via the account's token AND via the env System-User token (like the diagnose
            # probe, which reliably returns a comment-capable page token).
            if _pid.isdigit():
                for _src in (PAGE_ACCESS_TOKEN, _t):
                    if not (_src and len(_src) > 20):
                        continue
                    try:
                        # Direct page-token lookup (works when _src manages this page)
                        _pt = requests.get(f"{GRAPH_URL}/{_pid}?fields=access_token,instagram_business_account{{id}}&access_token={_src}", timeout=12)
                        if _pt.status_code == 200 and _pt.json().get("access_token"):
                            _t = _pt.json()["access_token"]
                            _igid = _igid or (_pt.json().get("instagram_business_account") or {}).get("id")
                            break
                        # Fallback: scan /me/accounts of _src for this page
                        _acc = requests.get(f"{GRAPH_URL}/me/accounts?fields=id,access_token,instagram_business_account{{id}}&limit=100&access_token={_src}", timeout=12)
                        if _acc.status_code == 200:
                            _hit = next((p for p in _acc.json().get("data", []) if str(p.get("id")) == _pid and p.get("access_token")), None)
                            if _hit:
                                _t = _hit["access_token"]
                                _igid = _igid or (_hit.get("instagram_business_account") or {}).get("id")
                                break
                    except Exception:
                        pass
            _add_page(_pid, _t, _igid, _t)

    # 1. Fetch Messenger Threads from EVERY page (up to 100 each)
    for _pg in pages_to_pull:
      fb_token = _pg["fb_token"]; fb_page_id = _pg["fb_page_id"]
      try:
        res = requests.get(
            f"{GRAPH_URL}/{fb_page_id}/conversations?platform=messenger&fields=id,updated_time,unread_count,senders{{id,name,profile_pic,link}},snippet&limit=100&access_token={fb_token}",
            timeout=15
        )
        if res.status_code == 200:
            data = res.json().get("data", [])
            for thread in data:
                t_id = thread.get("id")
                updated_time = thread.get("updated_time")
                unread = thread.get("unread_count", 0)
                senders = thread.get("senders", {}).get("data", [])
                snippet = thread.get("snippet", "")
                
                cust_sender = "عميل فيسبوك"
                cust_id = None
                avatar_url = ""
                profile_link = ""
                for s in senders:
                    if str(s.get("id")) != fb_page_id:
                        cust_sender = s.get("name", "عميل فيسبوك")
                        cust_id = s.get("id")
                        avatar_url = s.get("profile_pic", "")
                        profile_link = s.get("link", "")
                        break
                
                all_threads.append({
                    "id": t_id,
                    "client_id": cid,
                    "type": "messenger",
                    "channel": "messenger",
                    "platform": "facebook",
                    "customer_type": "lead",
                    "lead_score": 85,
                    "lead_badge": "Hot 🔥 85%",
                    "sender": cust_sender,
                    "sender_name": cust_sender,
                    "avatar_url": avatar_url,
                    "profile_link": profile_link,
                    "cust_id": cust_id,
                    "customer_id": cust_id,
                    "unread": unread,
                    "updated_time": updated_time,
                    "timestamp": updated_time,
                    "last_msg": snippet,
                    "snippet": snippet,
                    "messages": [
                        {"id": t_id, "text": snippet, "is_page": False, "sender_name": cust_sender, "time": updated_time}
                    ]
                })
      except Exception as e:
        print(f"[FB Messenger Error] {e}")

    # 2-4. Instagram DMs, Instagram comments, and Facebook comments — STRICTLY per the
    # active client's own pages (each with its own page token). Nothing is pulled when the
    # client has no connected pages, so an empty client shows an empty inbox (never Domya).
    for _pg in pages_to_pull:
        p_fb_page_id = _pg["fb_page_id"]; p_fb_token = _pg["fb_token"]
        p_ig_id = str(_pg.get("ig_id") or ""); p_ig_token = _pg.get("ig_token") or p_fb_token

        # 2. Instagram Direct messages
        if p_ig_id:
            try:
                res = requests.get(
                    f"{GRAPH_URL}/{p_ig_id}/conversations?platform=instagram&fields=id,updated_time,unread_count,senders{{id,name,username,profile_pic}}&limit=25&access_token={p_ig_token}",
                    timeout=15)
                resp_json = res.json()
                if res.status_code == 200 and "data" in resp_json:
                    for thread in resp_json.get("data", []):
                        t_id = thread.get("id"); updated_time = thread.get("updated_time")
                        unread = thread.get("unread_count", 0)
                        senders = thread.get("senders", {}).get("data", [])
                        cust_sender = "عميل إنستجرام"; cust_id = None; avatar_url = ""; profile_link = ""
                        for s in senders:
                            if str(s.get("id")) not in (p_ig_id, p_fb_page_id):
                                cust_sender = s.get("username", s.get("name", "عميل إنستجرام"))
                                cust_id = s.get("id"); avatar_url = s.get("profile_pic", "")
                                if s.get("username"): profile_link = f"https://instagram.com/{s.get('username')}"
                                break
                        all_threads.append({
                            "id": t_id, "client_id": cid, "type": "instagram", "channel": "instagram",
                            "platform": "instagram", "sender": f" {cust_sender}", "sender_name": f" {cust_sender}",
                            "avatar_url": avatar_url, "profile_link": profile_link, "cust_id": cust_id,
                            "customer_id": cust_id, "unread": unread, "updated_time": updated_time,
                            "timestamp": updated_time, "last_msg": "رسالة إنستجرام مباشرة",
                            "snippet": "رسالة إنستجرام مباشرة", "messages": []
                        })
            except Exception as e:
                print(f"[Instagram Direct Error] {e}")

        # 3. Instagram comments from posts/reels
        if p_ig_id:
            try:
                res = requests.get(
                    f"{GRAPH_URL}/{p_ig_id}/media?fields=id,caption,comments_count,timestamp,permalink,comments.limit(30){{id,text,username,timestamp}}&limit=50&access_token={p_ig_token}",
                    timeout=12)
                if res.status_code == 200:
                    for post in res.json().get("data", []):
                        comments_list = post.get("comments", {}).get("data", [])
                        if not comments_list: continue
                        caption = (post.get("caption") or "")[:50]
                        permalink = post.get("permalink", ""); post_time = post.get("timestamp", "")
                        for comment in comments_list:
                            c_id = comment.get("id"); c_text = comment.get("text", "")
                            c_user = comment.get("username", "عميل إنستجرام")
                            c_time = comment.get("timestamp", post_time)
                            all_threads.append({
                                "id": f"ig_comment_{c_id}", "client_id": cid, "type": "instagram",
                                "channel": CHANNEL_IG_COMMENT, "platform": "instagram", "is_comment": True,
                                "comment_id": c_id, "sender": f" @{c_user}", "sender_name": f" @{c_user}",
                                "cust_id": c_id, "customer_id": c_id, "unread": 1, "updated_time": c_time,
                                "timestamp": c_time, "last_msg": c_text,
                                "snippet": c_text if c_text.strip() else "(تعليق بدون نص)",
                                "permalink": permalink, "post_caption": caption,
                                "messages": [{"id": c_id, "text": c_text, "is_page": False, "sender_name": c_user, "time": c_time}]
                            })
            except Exception as e:
                print(f"[Instagram Comments Error] {e}")

        # 4. Facebook page post comments — use /feed. Requesting the commenter identity
        # (comments{from}) can make Meta reject the WHOLE request (needs extra access),
        # which is why comments showed as 0. Try WITHOUT `from` first (this is what works),
        # then optionally with `from` for names.
        try:
            # NOTE: requesting comments{from} makes Meta return posts with EMPTY comments
            # arrays (identity needs extra access), so we omit `from` and use a generic name.
            res = requests.get(
                f"{GRAPH_URL}/{p_fb_page_id}/feed?fields=id,message,created_time,permalink_url,comments.limit(50){{id,message,created_time}}&limit=50&access_token={p_fb_token}",
                timeout=15)
            if res.status_code == 200:
                for post in res.json().get("data", []):
                    comments_list = post.get("comments", {}).get("data", [])
                    if not comments_list: continue
                    post_msg = (post.get("message") or "")[:50]
                    permalink = post.get("permalink_url", ""); post_time = post.get("created_time", "")
                    for comment in comments_list:
                        c_id = comment.get("id"); c_text = comment.get("message", "")
                        c_from = comment.get("from", {}) or {}
                        c_user = c_from.get("name") or comment.get("username") or "عميل فيسبوك"
                        c_user_id = c_from.get("id")
                        c_time = comment.get("created_time", post_time)
                        all_threads.append({
                            "id": f"fb_comment_{c_id}", "client_id": cid, "type": "facebook",
                            "channel": CHANNEL_FB_COMMENT, "platform": "facebook", "is_comment": True,
                            "comment_id": c_id, "sender": f" {c_user}", "sender_name": f" {c_user}",
                            "cust_id": c_user_id or c_id, "customer_id": c_user_id or c_id, "unread": 1,
                            "updated_time": c_time, "timestamp": c_time, "last_msg": c_text,
                            "snippet": c_text if c_text.strip() else "(تعليق بدون نص)",
                            "permalink": permalink, "post_caption": post_msg,
                            "messages": [{"id": c_id, "text": c_text, "message": c_text, "is_page": False, "sender_name": c_user, "created_time": c_time, "time": c_time}]
                        })
        except Exception as e:
            print(f"[Facebook Comments Error] {e}")

    cid = current_client_id()
    pending = [p for p in pending_approvals if p.get("status") == "pending" and (p.get("client_id") or cid) == cid]
    
    draft_threads = []
    for item in pending:
        s = item.get("sender") or item.get("target_id") or "User"
        draft_threads.append({
            "id": f"draft_{item.get('id')}",
            "draft_id": item.get("id"),
            "type": item.get("type", "dm"),
            "channel": item.get("type", "dm"),
            "platform": item.get("platform", "facebook"),
            "customer_type": "lead",
            "lead_score": 85,
            "lead_badge": "مراجعة ⏳",
            "pending_approval": True,
            "ai_draft": item.get("reply", ""),
            "sender": str(s),
            "sender_name": f"عميل ({str(s)[:6]}) ⏳",
            "avatar_url": f"https://ui-avatars.com/api/?name={str(s)}&background=f59e0b&color=fff",
            "last_msg": item.get("message", ""),
            "snippet": item.get("message", ""),
            "timestamp": item.get("id", time.time()) / 1000 if item.get("id") else time.time(),
            "unread": 1,
            "messages": [
                {"id": f"msg_{item.get('id')}", "text": item.get("message", ""), "message": item.get("message", ""), "is_page": False, "sender_name": str(s), "created_time": item.get("time", "")}
            ]
        })

    all_threads = draft_threads + merge_and_sort(all_threads)
    
    client_threads = [t for t in all_threads if t.get("client_id") == cid]
    
    limit = safe_int(request.args.get("limit"), 200, 1, 500)
    offset = safe_int(request.args.get("offset"), 0, 0, 10000)
    paged_threads = client_threads[offset:offset+limit]

    # No demo/fake fallback: a client with no real conversations shows an empty inbox.

    res_data = {
        "threads": paged_threads,
        "conversations": paged_threads,
        "data": paged_threads,
        "total": len(client_threads),
        "has_more": offset + limit < len(client_threads),
        "next_offset": offset + limit,
        "pending": pending,
        "approval_mode": cache.get("approval_mode", "auto"),
        "active_client_id": cid,
    }
    conv_cache["all_threads"] = all_threads
    conv_cache["data"] = {"conversations": all_threads}
    conv_cache["timestamp"] = now
    return jsonify(res_data)


