@app.route("/api/send_reply", methods=["POST"])
def api_send_reply():
    data = request.get_json() or {}
    thread_id = str(data.get("thread_id") or data.get("recipient_id") or "")
    text = data.get("text", "").strip()
    reply_mode = data.get("reply_mode", "public")  # public | private | dm
    if not thread_id or not text:
        return jsonify({"error": "المستلم والنص مطلوبان"}), 400

    convo, cid = owned_thread_or_404(thread_id)
    if not convo:
        return jsonify({"error": "المحادثة غير موجودة"}), 404

    # Determine channel & target
    is_comment = thread_id.startswith("ig_comment_") or thread_id.startswith("fb_comment_")
    comment_id = thread_id.replace("ig_comment_", "").replace("fb_comment_", "") if is_comment else None

    # Get account access token for THIS client only (strict — no cross-client fallback)
    is_ig = thread_id.startswith("ig_comment_") or (isinstance(convo, dict) and convo.get("platform") == "instagram")
    client_accounts = [a for a in ACCOUNTS_STORE if a.get("client_id") == cid]
    # Prefer the account matching the thread's platform so the token can actually send here
    client_accounts.sort(key=lambda a: 0 if (a.get("platform") == ("instagram" if is_ig else "facebook")) else 1)
    token = PAGE_ACCESS_TOKEN
    for a in client_accounts:
        if a.get("access_token_enc"):
            t = decrypt(a["access_token_enc"])
            if t and len(t) > 20:
                token = t
                break
            elif a.get("access_token"):
                token = a["access_token"]
                break
        elif a.get("access_token"):
            token = a.get("access_token")
            break

    # Resolve a real PAGE token (PAGE_ACCESS_TOKEN may be a System User token that
    # cannot send /me/messages). Without this, replies silently fail to reach the customer.
    try:
        _acc = requests.get(
            f"{GRAPH_URL}/me/accounts?fields=id,access_token&limit=10&access_token={token}", timeout=10)
        if _acc.status_code == 200:
            _pages = _acc.json().get("data", [])
            if _pages and _pages[0].get("access_token"):
                token = _pages[0]["access_token"]
    except Exception as _ex:
        print(f"[Send Token Exchange] {_ex}")

    try:
        if is_comment and reply_mode == "public":
            # Public reply under the comment. Facebook uses /{comment}/comments,
            # Instagram uses /{comment}/replies — route to the correct one.
            _is_ig_comment = thread_id.startswith("ig_comment_")
            url = f"{GRAPH_URL}/{comment_id}/{'replies' if _is_ig_comment else 'comments'}"
            res = requests.post(url, params={"access_token": token}, data={"message": text}, timeout=15)
            # Fallback to the other edge if Meta rejects the first form
            if res.status_code >= 400:
                alt = f"{GRAPH_URL}/{comment_id}/{'comments' if _is_ig_comment else 'replies'}"
                res_alt = requests.post(alt, params={"access_token": token}, data={"message": text}, timeout=15)
                if res_alt.status_code < 400:
                    res = res_alt
            res_data = {}
            try:
                res_data = res.json()
            except:
                pass

            if res.status_code >= 400 or "error" in res_data:
                err_obj = res_data.get("error") or {}
                err_msg = err_obj.get("message") or "فشل الإرسال عبر Meta Graph API"
                return jsonify({
                    "ok": False,
                    "status": "failed",
                    "graph_status": res.status_code,
                    "error_code": err_obj.get("code"),
                    "error_subcode": err_obj.get("error_subcode"),
                    "error": f"فشل الإرسال عبر Meta (كود {res.status_code}): {err_msg}"
                }), 400
            
            log_event("comment_public", f"Comment_{comment_id[:6]}", "رد علني تحت المنشور", text)
            new_msg = {
                "id": f"msg_sent_{int(time.time()*1000)}",
                "text": text,
                "message": text,
                "is_page": True,
                "sender_name": "Domya Moderator",
                "created_time": datetime.now().strftime("%I:%M %p"),
                "created_at": datetime.now(timezone.utc).isoformat(),
                "source": "human"
            }
            if isinstance(convo, dict):
                if "messages" not in convo or not isinstance(convo["messages"], list):
                    convo["messages"] = []
                convo["messages"].append(new_msg)
                convo["last_msg"] = text
                convo["snippet"] = text

            return jsonify({"ok": True, "status": "sent", "mode": "public", "graph_status": res.status_code, "id": res_data.get("id"), "message": new_msg})

        elif is_comment and reply_mode == "private":
            # Private DM reply to comment sender
            url = f"{GRAPH_URL}/me/messages"
            payload = {"recipient": {"comment_id": comment_id}, "message": {"text": text}}
            res = requests.post(url, params={"access_token": token}, json=payload, timeout=15)
            res_data = {}
            try:
                res_data = res.json()
            except:
                pass

            if res.status_code >= 400 or "error" in res_data:
                err_obj = res_data.get("error") or {}
                err_msg = err_obj.get("message") or "فشل الإرسال عبر Meta Graph API"
                return jsonify({
                    "ok": False,
                    "status": "failed",
                    "graph_status": res.status_code,
                    "error_code": err_obj.get("code"),
                    "error_subcode": err_obj.get("error_subcode"),
                    "error": f"فشل الإرسال عبر Meta (كود {res.status_code}): {err_msg}"
                }), 400

            log_event("comment_private", f"Comment_{comment_id[:6]}", "رد خاص (DM)", text)
            return jsonify({"ok": True, "status": "sent", "mode": "private", "graph_status": res.status_code, "id": res_data.get("id")})

        else:
            # Standard DM reply
            recipient_id = thread_id
            if isinstance(convo, dict) and convo.get("cust_id"):
                recipient_id = str(convo.get("cust_id"))
            ok_send, detail = send_dm_reply(recipient_id, text, access_token=token)
            if not ok_send:
                return jsonify({"ok": False, "status": "failed",
                                "error": f"فشل إرسال الرسالة عبر Meta: {detail}"}), 400
            log_event("dm", f"User_{recipient_id[:6]}", "رد مباشر", text)

            # Persist sent message in conversation memory so it appears in thread history
            new_msg = {
                "id": f"msg_sent_{int(time.time()*1000)}",
                "text": text,
                "message": text,
                "is_page": True,
                "sender_name": "Domya Moderator",
                "created_time": datetime.now().strftime("%I:%M %p"),
                "created_at": datetime.now(timezone.utc).isoformat(),
                "source": "human"
            }
            if isinstance(convo, dict):
                if "messages" not in convo or not isinstance(convo["messages"], list):
                    convo["messages"] = []
                convo["messages"].append(new_msg)
                convo["last_msg"] = text
                convo["snippet"] = text

            return jsonify({"ok": True, "status": "sent", "mode": "dm", "message": new_msg})

    except Exception as e:
        print(f"[Send Reply Error] {e}")
        return jsonify({"ok": False, "error": f"خطأ بالخادم: {str(e)}"}), 500


