@app.route("/api/approve/<int:draft_id>", methods=["POST"])
def api_approve_draft(draft_id):
    data = request.get_json() or {}
    draft = next((p for p in pending_approvals if p.get("id") == draft_id), None)
    if not draft:
        return jsonify({"error": "Draft not found"}), 404
    
    reply = data.get("reply", draft.get("reply"))
    private_reply = data.get("private_reply", draft.get("private_reply"))
    
    if draft["type"] == "dm":
        send_dm_reply(draft["target_id"], reply)
        log_event("dm", draft["sender"], draft["message"], reply)
    elif draft["type"] == "comment":
        send_comment_reply(draft["target_id"], reply)
        if private_reply:
            send_private_comment_reply(draft["target_id"], private_reply)
            log_event("comment", draft["sender"], draft["message"], reply, private_reply=private_reply)
        else:
            log_event("comment", draft["sender"], draft["message"], reply)
            
    draft["status"] = "approved"
    
    push_setting("meta_ai_pending", pending_approvals)
    return jsonify({"ok": True, "status": "approved"})

