@app.route("/api/upload_doc", methods=["POST"])
def api_upload_doc():
    data = request.get_json() or {}
    text = data.get("text", "").strip()
    if not text:
        return jsonify({"error": "No text provided"}), 400
    
    paragraphs = [p.strip() for p in re.split(r'\n\s*\n|\r\n\s*\r\n', text) if len(p.strip()) > 10]
    if not paragraphs:
        paragraphs = [p.strip() for p in text.split("\n") if len(p.strip()) > 10]
    
    kb = get_kb_data()
    cid = current_client_id()
    added_chunks = 0
    base_id = int(time.time())

    for i, p in enumerate(paragraphs):
        first_line = p.split("\n")[0][:50]
        q_title = f"معلومات: {first_line}" if len(first_line) > 5 else f"معلومات الشركة #{i+1}"
        new_item = {"id": base_id + i, "question": q_title, "answer": p, "client_id": cid}
        kb.append(new_item)
        added_chunks += 1
        
    cache["kb"] = kb
    push_setting("meta_ai_kb", kb)

    # Also push chunks to Supabase public.documents vector table if Supabase is configured
    if SUPABASE_URL and SUPABASE_KEY:
        try:
            for p in paragraphs:
                emb = generate_embedding(p)
                doc_payload = {
                    "content": p,
                    "metadata": {"source": "doc_upload"},
                    "client_id": cid
                }
                if emb and len(emb) == 1536:
                    doc_payload["embedding"] = emb
                requests.post(f"{SUPABASE_URL}/rest/v1/documents", headers=supa_headers(), json=doc_payload, timeout=5)
        except Exception as _ex:
            print(f"[Supabase Vector Document Insert Error] {_ex}")

    return jsonify({"ok": True, "chunks": added_chunks, "total_kb": len(kb)})

