def discover_pages(user_token):
    IG = 'id,username,profile_picture_url,followers_count'
    found = {}

    def add(p):
        if p.get('id'):
            found[str(p['id'])] = {**found.get(str(p['id']), {}), **{k: v for k, v in p.items() if v}}

    try:
        r = requests.get(f'{GRAPH_URL}/me/accounts', params={
            'access_token': user_token, 'limit': 100,
            'fields': f'id,name,access_token,picture{{url}},fan_count,instagram_business_account{{{IG}}}',
        }, timeout=30).json()
        for p in r.get('data', []):
            add(p)
    except Exception as e:
        print('[discover] me/accounts:', e)

    try:
        for b in requests.get(f'{GRAPH_URL}/me/businesses',
                              params={'access_token': user_token, 'fields': 'id,name'},
                              timeout=30).json().get('data', []):
            for edge in ('owned_pages', 'client_pages'):
                try:
                    for p in requests.get(f"{GRAPH_URL}/{b['id']}/{edge}",
                                          params={'access_token': user_token,
                                                  'fields': 'id,name,picture{url},fan_count'},
                                          timeout=30).json().get('data', []):
                        add(p)
                except Exception:
                    pass
    except Exception as e:
        print('[discover] businesses:', e)

    for pid, p in list(found.items()):
        if p.get('access_token'):
            continue
        try:
            r = requests.get(f'{GRAPH_URL}/{pid}', params={
                'access_token': user_token,
                'fields': f'access_token,name,picture{{url}},fan_count,instagram_business_account{{{IG}}}',
            }, timeout=20).json()
            if 'error' not in r:
                add({**r, 'id': pid})
        except Exception:
            pass

    return list(found.values())

@app.route("/oauth_callback")
@app.route("/api/oauth/callback")
def oauth_callback():
    if request.args.get('error'):
        return redirect('/?oauth=error&reason=denied')

    code = request.args.get('code')
    if not code:
        return redirect('/?oauth=error&reason=nocode')

    state = request.args.get('state')
    expected_state = request.cookies.get('oauth_state')
    code_verifier = request.cookies.get('oauth_code_verifier')
    
    if not expected_state or not state or state != expected_state:
        print("[OAuth Warning] Mismatched state token")
        return redirect('/?oauth=error&reason=state')

    meta_app_id = os.environ.get('META_APP_ID', '1331918902446123')
    meta_app_secret = os.environ.get('META_APP_SECRET', '')
    
    redirect_uri = "https://metaaimoderator.vercel.app/api/oauth/callback"

    try:
        params = {
            'client_id': meta_app_id,
            'client_secret': meta_app_secret,
            'redirect_uri': redirect_uri,
            'code': code,
        }
        if code_verifier:
            params['code_verifier'] = code_verifier
        short_res = requests.get(f'{GRAPH_URL}/oauth/access_token', params=params, timeout=10).json()

        short = short_res.get('access_token')
        if not short:
            err_msg = short_res.get('error', {}).get('message', 'Token exchange failed')
            print(f"[OAuth Exchange Error] {short_res}")
            return redirect(f'/?oauth=error&reason=token_exchange_failed&details={quote(err_msg)}')

        long_tok_res = requests.get(f'{GRAPH_URL}/oauth/access_token', params={
            'grant_type': 'fb_exchange_token',
            'client_id': meta_app_id,
            'client_secret': meta_app_secret,
            'fb_exchange_token': short,
        }, timeout=10).json()

        long_token = long_tok_res.get('access_token', short)

        session.permanent = True
        session['uid'] = session.get('uid') or os.environ.get("ADMIN_USER", "admin")
        session['authenticated'] = True

        target_client = request.cookies.get('oauth_client_id') or session.get('oauth_client_id') or current_client_id()
        session['oauth_client_id'] = target_client
        session['active_client_id'] = target_client

        try:
            pages = discover_pages(long_token)
            if pages:
                # Auto-link EVERY page the user approved on Facebook's own consent screen —
                # no website page-picker. Each page becomes its own client workspace.
                global ACCOUNTS_STORE
                linked = 0
                target_client_obj = next((c for c in AGENCY_CLIENTS_STORE if c.get('id') == target_client), None)
                
                for i, page in enumerate(pages):
                    ptok = page.get('access_token') or long_token
                    pid = str(page.get('id'))
                    if not pid:
                        continue
                    
                    pcid = "client_" + pid
                    if target_client_obj:
                        if target_client_obj.get('page_id') == pid:
                            pcid = target_client
                        elif target_client_obj.get('name') == page.get('name') and not target_client_obj.get('page_id'):
                            pcid = target_client
                        elif len(pages) == 1 and not target_client_obj.get('page_id'):
                            pcid = target_client

                    cobj = next((c for c in AGENCY_CLIENTS_STORE if c.get('id') == pcid), None)
                    if not cobj:
                        cobj = {"id": pcid, "name": page.get('name') or "عميل", "company": page.get('name') or "",
                                "package": "Business VIP", "status": "active", "is_active": True}
                        AGENCY_CLIENTS_STORE.append(cobj)
                    
                    # Only overwrite name if it's a new auto-generated client
                    if pcid != target_client:
                        cobj['name'] = page.get('name') or cobj.get('name')
                        cobj['company'] = page.get('name') or cobj.get('company')
                        
                    cobj['page_id'] = pid
                    cobj['fb_connected'] = True
                    exp = (datetime.now(timezone.utc) + timedelta(days=60)).isoformat()
                    
                    fb_acc = {"id": pid, "name": page.get('name'), "platform": "facebook", "client_id": pcid,
                              "avatar_url": (page.get('picture') or {}).get('data', {}).get('url') if isinstance(page.get('picture'), dict) else None,
                              "access_token": ptok, "access_token_enc": encrypt(ptok),
                              "token_expires_at": exp, "status": "connected", "dm_mode": "auto", "comment_mode": "auto"}
                    
                    ACCOUNTS_STORE = [a for a in ACCOUNTS_STORE if str(a.get('id')) != pid]
                    ACCOUNTS_STORE.append(fb_acc)
                    
                    ig = page.get('instagram_business_account')
                    if ig and ig.get('id'):
                        igid = str(ig['id'])
                        cobj['ig_id'] = igid
                        cobj['ig_connected'] = True
                        
                        ig_acc = {"id": igid, "name": ig.get('username') or page.get('name'), "platform": "instagram",
                                  "ig_id": igid, "client_id": pcid, "parent_page_id": pid,
                                  "access_token": ptok, "access_token_enc": encrypt(ptok),
                                  "token_expires_at": exp, "status": "connected", "dm_mode": "auto", "comment_mode": "auto"}

                        # Remove any prior entry for this IG account (plain id, composite id,
                        # or matching ig_id) so we never create duplicate IG rows.
                        ACCOUNTS_STORE = [a for a in ACCOUNTS_STORE
                                          if str(a.get('id')) != igid
                                          and str(a.get('id')) != f"{igid}_{pcid}"
                                          and not (a.get('platform') == 'instagram' and str(a.get('ig_id')) == igid and a.get('client_id') == pcid)]
                        ACCOUNTS_STORE.append(ig_acc)
                    
                    try:
                        requests.post(f"{GRAPH_URL}/{pid}/subscribed_apps",
                                      params={'subscribed_fields': 'messages,messaging_postbacks,feed', 'access_token': ptok}, timeout=8)
                    except Exception:
                        pass
                    linked += 1
                push_setting("meta_ai_accounts", ACCOUNTS_STORE)
                push_setting("meta_ai_clients", AGENCY_CLIENTS_STORE)
                cache["accounts"] = ACCOUNTS_STORE
                cache["clients"] = AGENCY_CLIENTS_STORE
                session.modified = True
                return redirect(f'/?oauth=success&linked={linked}')
        except Exception as ex:
            print(f"[OAuth Auto-Link Error] {ex}")

        return redirect('/?oauth=error&reason=nopages')
    except Exception as e:
        print(f"[OAuth General Error] {e}")
        return redirect('/?oauth=error&reason=exception')

@app.route('/api/oauth/pending_pages', methods=['GET'])
def api_pending_pages():
    tok = session.get('pending_token')
    discovered = discover_pages(tok) if tok else []
    # Show ONLY the pages the current OAuth session just authorized — never merge other
    # clients' already-connected pages, which caused mixing (e.g. a new person's FB page
    # shown next to Domya's page/Instagram).
    found_dict = {str(p['id']): p for p in discovered if p.get('id')}
    pages = list(found_dict.values())
    return jsonify({
        'client_id': session.get('oauth_client_id'),
        'pages': [{
            'id': str(p['id']),
            'name': p.get('name'),
            'picture': (p.get('picture') or {}).get('data', {}).get('url') if isinstance(p.get('picture'), dict) else p.get('picture'),
            'followers': p.get('fan_count'),
            'instagram': (p.get('instagram_business_account') or {}).get('username') if isinstance(p.get('instagram_business_account'), dict) else p.get('instagram'),
        } for p in pages]
    })

@app.route('/api/oauth/attach_page', methods=['POST'])
def api_attach_page():
    data = request.get_json() or {}
    page_id = str(data.get('page_id', ''))
    client_id = data.get('client_id') or session.get('oauth_client_id') or request.cookies.get('oauth_client_id') or current_client_id()
    tok = session.get('pending_token')
    pages = discover_pages(tok) if tok else []
    page = next((p for p in pages if str(p['id']) == page_id), None)
    
    if not page and pages:
        page = pages[0]
        page_id = str(page['id'])

    if not page:
        return jsonify({'error': 'الصفحة غير موجودة'}), 404

    tok = page.get('access_token') or PAGE_ACCESS_TOKEN
    expires = (datetime.now(timezone.utc) + timedelta(days=60)).isoformat()

    existing_fb = next((a for a in ACCOUNTS_STORE if str(a['id']) == str(page['id'])), None)
    fb_account = {
        'client_id': client_id,
        'platform': 'facebook',
        'id': str(page['id']),
        'name': page.get('name'),
        'avatar_url': (page.get('picture') or {}).get('data', {}).get('url'),
        'access_token': tok,
        'access_token_enc': encrypt(tok),
        'token_expires_at': expires,
        'status': 'connected',
    }
    if existing_fb:
        existing_fb.update(fb_account)
    else:
        ACCOUNTS_STORE.append(fb_account)

    client_obj = next((c for c in AGENCY_CLIENTS_STORE if c.get('id') == client_id), None)
    if not client_obj:
        # The target client no longer exists (lost during the multi-step OAuth flow) —
        # create a workspace for this page so the accounts are never left orphaned.
        client_id = client_id or ("client_" + str(page['id']))
        client_obj = {
            "id": client_id,
            "name": page.get('name') or "عميل جديد",
            "company": page.get('name') or "",
            "package": "Business VIP",
            "status": "active",
            "is_active": True,
        }
        AGENCY_CLIENTS_STORE.append(client_obj)
    fb_account['client_id'] = client_id
    client_obj['page_id'] = str(page['id'])
    client_obj['fb_connected'] = True

    ig = page.get('instagram_business_account')
    if ig:
        existing_ig = next((a for a in ACCOUNTS_STORE if str(a['id']) == str(ig['id'])), None)
        ig_account = {
            'client_id': client_id,
            'platform': 'instagram',
            'id': str(ig['id']),
            'name': ig.get('username'),
            'avatar_url': ig.get('profile_picture_url'),
            'access_token': tok,
            'access_token_enc': encrypt(tok),
            'token_expires_at': expires,
            'status': 'connected',
            'parent_page_id': str(page['id']),
        }
        if existing_ig:
            existing_ig.update(ig_account)
        else:
            ACCOUNTS_STORE.append(ig_account)

        if client_obj:
            client_obj['ig_id'] = str(ig['id'])
            client_obj['ig_connected'] = True

    try:
        requests.post(f"{GRAPH_URL}/{page['id']}/subscribed_apps", params={
            'subscribed_fields': 'messages,messaging_postbacks,feed',
            'access_token': tok,
        }, timeout=20)
    except Exception as e:
        print('[subscribe warning]', e)

    session.pop('pending_token', None)
    session.pop('oauth_client_id', None)
    session.modified = True
    
    push_setting("meta_ai_accounts", ACCOUNTS_STORE)
    push_setting("meta_ai_clients", AGENCY_CLIENTS_STORE)
    
    return jsonify({
        'ok': True,
        'facebook': page.get('name'),
        'instagram': ig.get('username') if ig else None
    })

#  Auth Guard — blocks ALL /api/* without session
admin_user = os.environ.get("ADMIN_USER") or "admin"
# No insecure default: if ADMIN_PASS isn't set, generate a random one (no known backdoor).
admin_pass = os.environ.get("ADMIN_PASS") or secrets.token_urlsafe(18)

def hash_password(pw):
    salt = secrets.token_hex(8)
    h = hashlib.sha256((salt + str(pw)).encode("utf-8")).hexdigest()
    return f"sha256${salt}${h}"

def verify_password(stored, pw):
    if not stored:
        return False
    s = str(stored)
    if s.startswith("sha256$"):
        try:
            _, salt, h = s.split("$", 2)
            calc = hashlib.sha256((salt + str(pw)).encode("utf-8")).hexdigest()
            return hmac.compare_digest(calc, h)
        except Exception:
            return False
    # Legacy plaintext record — constant-time compare
    return hmac.compare_digest(s, str(pw))

USERS_DB = {
    admin_user: {"username": admin_user, "password": hash_password(admin_pass),
                 "role": "admin", "assigned_clients": []},
}

# ---- Role-based access helpers ----
def current_username():
    return session.get("uid") if has_request_context() else None

def current_user_rec():
    return USERS_DB.get(current_username() or "", {})

def current_role():
    if has_request_context() and session.get("role"):
        return session.get("role")
    return current_user_rec().get("role", "account_manager")

def is_admin():
    return current_role() == "admin"

def is_manager():
    # admin or account_manager (i.e. not a plain employee) — can manage/assign.
    return current_role() in ("admin", "account_manager")

def is_employee():
    return current_role() == "employee"

def assigned_client_ids():
    """Client ids the current user is allowed to see. Admins see all."""
    if is_admin():
        return [c.get("id") for c in AGENCY_CLIENTS_STORE]
    return list(current_user_rec().get("assigned_clients") or [])

def can_see_client(cid):
    return is_admin() or (cid in assigned_client_ids())

def require_admin(f):
    @wraps(f)
    def _w(*a, **k):
        if not is_admin():
            return jsonify({"error": "صلاحيات المدير مطلوبة"}), 403
        return f(*a, **k)
    return _w

def require_manager(f):
    """Admin or Account Manager only (blocks plain employees)."""
    @wraps(f)
    def _w(*a, **k):
        if not is_manager():
            return jsonify({"error": "صلاحيات المدير أو مدير الحسابات مطلوبة"}), 403
        return f(*a, **k)
    return _w

PUBLIC_PATHS = {
    '/api/login', '/api/logout', '/api/me',
    '/webhook', '/api/oauth_url',
    '/api/oauth/callback', '/oauth_callback',
    '/api/auth/facebook',
    '/api/cron/refresh_tokens',
    '/api/cron/process_scheduled',
    '/api/telegram/attendance',
    '/api/telegram/attendance/diag',
    '/api/telegram/attendance/setup',
    '/api/drive/diag',
    '/api/telegram/bots',
    '/api/telegram/attendance/welcome',
    '/api/telegram/tasks',
    '/api/telegram/tasks/setup',
    '/api/employees/clear-demo',
    '/api/hr/cleanup',
    '/api/oauth/pending_pages',
    '/api/oauth/attach_page',
    '/api/oauth/start',
    '/api/data-deletion',
    '/api/health',
}

@app.before_request
def global_api_guard():
    p = request.path
    if not p.startswith('/api/'):
        return
    if p in PUBLIC_PATHS:
        return
    if request.method == 'OPTIONS':
        return
    
    # Check Bearer or API Key auth header for secure endpoints or API access
    auth_header = request.headers.get("Authorization", "")
    api_key_header = request.headers.get("X-API-Key", "")
    expected_secret = os.environ.get("ADMIN_API_KEY") or os.environ.get("APP_SECRET") or os.environ.get("SECRET_KEY")
    if expected_secret:
        if auth_header.startswith("Bearer "):
            token = auth_header[7:].strip()
            if hmac.compare_digest(token, expected_secret):
                return
        if api_key_header and hmac.compare_digest(api_key_header, expected_secret):
            return

    if 'uid' not in session:
        return jsonify({"error": "Unauthorized"}), 401

