    # Cascade delete: remove associated KB, rules, accounts
    global ACCOUNTS_STORE
    ACCOUNTS_STORE = [a for a in ACCOUNTS_STORE if a.get("client_id") != cid]
    kb = get_kb_data()
    kb = [item for item in kb if item.get("client_id") != cid]
