@app.route("/api/cron/refresh_tokens", methods=["GET"])
def api_cron_refresh_tokens():
    refreshed = 0
    for acc in ACCOUNTS_STORE:
        tok_enc = acc.get("access_token_enc")
        if tok_enc:
            try:
                tok = decrypt(tok_enc)
                if tok and len(tok) > 20:
                    r = requests.get(f"https://graph.facebook.com/v21.0/oauth/access_token?grant_type=fb_exchange_token&client_id={os.environ.get('META_APP_ID','1331918902446123')}&client_secret={os.environ.get('META_APP_SECRET','')}&fb_exchange_token={tok}", timeout=5)
                    if r.status_code == 200:
                        new_tok = r.json().get("access_token")
                        if new_tok:
                            acc["access_token_enc"] = encrypt(new_tok)
                            acc["token_expires"] = (datetime.now(timezone.utc) + timedelta(days=60)).isoformat()
                            refreshed += 1
            except Exception as e:
                print(f"[Cron Refresh] {acc.get('id')}: {e}")
    if refreshed:
        push_setting("meta_ai_accounts", ACCOUNTS_STORE)
    return jsonify({"ok": True, "refreshed": refreshed})


#  Migrate & Clean Accounts 
def cleanup_placeholder_accounts():
    seen = set()
    cleaned = []
    for a in ACCOUNTS_STORE:
        key = (a.get("platform"), str(a.get("id")))
        if key in seen:
            continue
        seen.add(key)
        cleaned.append(a)
    ACCOUNTS_STORE[:] = cleaned


def migrate_accounts():
    changed = False
    for acc in ACCOUNTS_STORE:
        if not acc.get("client_id"):
            pid = str(acc.get("page_id", acc.get("id", "")))
            matched = next((c for c in AGENCY_CLIENTS_STORE
                           if str(c.get("page_id","")) == pid or str(c.get("ig_id","")) == pid), None)
            acc["client_id"] = matched["id"] if matched else "client_default"
            changed = True
    if changed:
        push_setting("meta_ai_accounts", ACCOUNTS_STORE)



def upsert_account(acc):
    for i, a in enumerate(ACCOUNTS_STORE):
        if str(a.get("platform")) == str(acc.get("platform")) and str(a.get("id")) == str(acc.get("id")):
            ACCOUNTS_STORE[i] = {**a, **acc}
            push_setting("meta_ai_accounts", ACCOUNTS_STORE)
            return
    ACCOUNTS_STORE.append(acc)
    push_setting("meta_ai_accounts", ACCOUNTS_STORE)

cleanup_placeholder_accounts()

migrate_accounts()



