# 
# Chatwoot Open Source - Page Verification & Health Check Logic
# 

def verify_page_token_status(page_id, access_token):
    if not access_token:
        return {"status": "disconnected", "permissions": []}
    try:
        res = requests.get(f"{GRAPH_URL}/{page_id}", params={"access_token": access_token, "fields": "name,id,instagram_business_account"}, timeout=5)
        if res.status_code != 200:
            return {"status": "expired", "permissions": []}
        
        perm_res = requests.get(f"{GRAPH_URL}/me/permissions", params={"access_token": access_token}, timeout=5)
        granted = []
        if perm_res.status_code == 200:
            granted = [p["permission"] for p in perm_res.json().get("data", []) if p.get("status") == "granted"]
            
        required = ["pages_messaging", "pages_read_engagement", "instagram_basic", "instagram_manage_messages"]
        has_all = all(r in granted for r in required)
        
        status = "verified" if (has_all or len(granted) >= 2) else "needs_reauth"
        return {"status": status, "permissions": granted}
    except Exception as e:
        print(f"[Verification Error] {e}")
        return {"status": "error", "permissions": []}

