# 
# Chatwoot Middleware API Integration
# 

CHATWOOT_URL = os.environ.get("CHATWOOT_URL", "https://app.chatwoot.com")
CHATWOOT_API_KEY = os.environ.get("CHATWOOT_API_KEY", "")
CHATWOOT_ACCOUNT_ID = os.environ.get("CHATWOOT_ACCOUNT_ID", "1")

def chatwoot_headers():
    return {
        "api_access_token": CHATWOOT_API_KEY,
        "Content-Type": "application/json"
    }

def get_conversations_from_chatwoot():
    if not CHATWOOT_API_KEY:
        return None
    try:
        url = f"{CHATWOOT_URL}/api/v1/accounts/{CHATWOOT_ACCOUNT_ID}/conversations"
        r = requests.get(url, headers=chatwoot_headers(), timeout=5)
        if r.status_code == 200:
            return r.json().get("data", {}).get("payload", [])
    except Exception as e:
        print(f"[Chatwoot API Error] {e}")
    return None

def send_reply_via_chatwoot(conversation_id, message_text):
    if not CHATWOOT_API_KEY:
        return False
    try:
        url = f"{CHATWOOT_URL}/api/v1/accounts/{CHATWOOT_ACCOUNT_ID}/conversations/{conversation_id}/messages"
        r = requests.post(url, headers=chatwoot_headers(), json={
            "content": message_text,
            "message_type": "outgoing",
            "private": False
        }, timeout=5)
        return r.status_code == 200
    except Exception as e:
        print(f"[Chatwoot Send Error] {e}")
        return False

def send_private_note_via_chatwoot(conversation_id, message_text):
    """يسيب اقتراح الـ AI كـ private note جوه المحادثة عشان الـ agent يوافق ويبعت بنفسه (وضع DM اليدوي)."""
    if not CHATWOOT_API_KEY:
        return False
    try:
        url = f"{CHATWOOT_URL}/api/v1/accounts/{CHATWOOT_ACCOUNT_ID}/conversations/{conversation_id}/messages"
        r = requests.post(url, headers=chatwoot_headers(), json={
            "content": message_text,
            "message_type": "outgoing",
            "private": True
        }, timeout=5)
        return r.status_code == 200
    except Exception as e:
        print(f"[Chatwoot Note Error] {e}")
        return False


@app.route('/api/chatwoot/webhook', methods=['POST'])
def api_chatwoot_webhook():
    """
    يستقبل حدث message_created من Chatwoot، يشغّل الـ AI، ويرد:
      - كومنت عام  -> رد تلقائي مباشر (outgoing)
      - رسالة خاصة -> اقتراح AI كـ private note للموافقة اليدوية
    """
    # تحقق اختياري بمفتاح مشترك (لو CHATWOOT_WEBHOOK_SECRET متظبط في الـ env)
    expected = os.environ.get("CHATWOOT_WEBHOOK_SECRET", "")
    if expected:
        got = request.headers.get("X-Webhook-Secret") or request.args.get("secret") or ""
        if not hmac.compare_digest(got, expected):
            return jsonify({"error": "unauthorized"}), 401

    data = request.get_json(silent=True) or {}

    # نعالج بس إنشاء رسالة جديدة
    if data.get("event") != "message_created":
        return jsonify({"status": "ignored", "reason": "not message_created"}), 200

    # نتجاهل ردودنا الصادرة عشان منعملش loop لا نهائي
    if data.get("message_type") != "incoming":
        return jsonify({"status": "ignored", "reason": "not incoming"}), 200

    content = (data.get("content") or "").strip()
    conv = data.get("conversation") or {}
    conversation_id = conv.get("id") or (data.get("conversation_id"))
    message_id = data.get("id")

    if not conversation_id or not content:
        return jsonify({"status": "ignored", "reason": "no conversation_id or content"}), 200

    # منع المعالجة المكررة لنفس الرسالة (Chatwoot ممكن يعيد الإرسال)
    dedup_key = f"cw_msg_{message_id}"
    if message_id is not None and free_lru_cache.get(dedup_key):
        return jsonify({"status": "ignored", "reason": "duplicate"}), 200
    if message_id is not None:
        free_lru_cache.set(dedup_key, True, ttl_seconds=3600)

    # تحديد القناة/النوع: كومنت عام ولا DM
    add_attr = conv.get("additional_attributes") or {}
    content_attr = data.get("content_attributes") or {}
    channel = str(conv.get("channel") or data.get("channel") or "").lower()
    is_comment = (
        str(add_attr.get("type", "")).lower() == "comment"
        or bool(content_attr.get("comment_id"))
        or "comment" in channel
    )
    platform = "instagram" if "instagram" in channel else "facebook"

    # إجبار الوضع اليدوي على كل القنوات لو الـ env متظبط
    force_private = os.environ.get("CHATWOOT_ALWAYS_PRIVATE", "").lower() in ("1", "true", "yes")

    reply = generate_reply(content, platform=platform, client_id=current_client_id())

    if is_comment and not force_private:
        ok = send_reply_via_chatwoot(conversation_id, reply)
        mode = "auto_public"
    else:
        ok = send_private_note_via_chatwoot(conversation_id, reply)
        mode = "private_note"

    try:
        log_event("chatwoot_" + mode, str(conversation_id), content, reply)
    except Exception:
        pass

    return jsonify({"status": "ok" if ok else "send_failed", "mode": mode, "reply": reply}), 200


