# Live Google OAuth2 & Telegram Bot Credentials Integration (Dynamic)
# =========================================================
GOOGLE_CLIENT_ID = os.environ.get("GOOGLE_CLIENT_ID", "")
GOOGLE_CLIENT_SECRET = os.environ.get("GOOGLE_CLIENT_SECRET", "")
GOOGLE_DRIVE_REFRESH_TOKEN = os.environ.get("GOOGLE_DRIVE_REFRESH_TOKEN", "")
TELEGRAM_TASKS_BOT_TOKEN = os.environ.get("TELEGRAM_TASKS_BOT_TOKEN", "")
TELEGRAM_ATTENDANCE_BOT_TOKEN = os.environ.get("TELEGRAM_ATTENDANCE_BOT_TOKEN", "")

def get_google_oauth_access_token():
    try:
        data = urllib.parse.urlencode({
            "client_id": GOOGLE_CLIENT_ID,
            "client_secret": GOOGLE_CLIENT_SECRET,
            "refresh_token": GOOGLE_DRIVE_REFRESH_TOKEN,
            "grant_type": "refresh_token"
        }).encode("utf-8")

        req = urllib.request.Request(
            "https://oauth2.googleapis.com/token",
            data=data,
            headers={"Content-Type": "application/x-www-form-urlencoded"}
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            token_res = json.loads(resp.read().decode("utf-8"))
            return token_res.get("access_token")
    except Exception as e:
        print(f"[Google OAuth Refresh Exception] {e}")
        return None

def create_google_drive_client_folder(folder_name):
    token = get_google_oauth_access_token()
    if not token:
        return None
    try:
        folder_metadata = {
            "name": folder_name,
            "mimeType": "application/vnd.google-apps.folder"
        }
        req = urllib.request.Request(
            "https://www.googleapis.com/drive/v3/files",
            data=json.dumps(folder_metadata).encode("utf-8"),
            headers={
                "Authorization": f"Bearer {token}",
                "Content-Type": "application/json"
            }
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            res = json.loads(resp.read().decode("utf-8"))
            fid = res.get("id")
            if fid:
                return f"https://drive.google.com/drive/folders/{fid}"
    except Exception as e:
        print(f"[Google Drive Create Folder Exception] {e}")
    return None

def drive_upload_bytes(name, data, mime, parent_url=None):
    """Upload raw bytes to Drive (multipart), make it link-readable, return a shareable URL."""
    token = get_google_oauth_access_token()
    if not token:
        return None
    try:
        meta = {"name": name}
        pid = drive_file_id(parent_url) if parent_url else None
        if pid:
            meta["parents"] = [pid]
        boundary = "domya_boundary_7fbc"
        body = b""
        body += ("--" + boundary + "\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n").encode()
        body += (json.dumps(meta) + "\r\n").encode()
        body += ("--" + boundary + "\r\nContent-Type: " + mime + "\r\n\r\n").encode()
        body += data + ("\r\n--" + boundary + "--\r\n").encode()
        req = urllib.request.Request(
            "https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id",
            data=body,
            headers={"Authorization": f"Bearer {token}",
                     "Content-Type": f"multipart/related; boundary={boundary}"}
        )
        with urllib.request.urlopen(req, timeout=25) as resp:
            fid = json.loads(resp.read().decode("utf-8")).get("id")
        if not fid:
            return None
        # make anyone-with-link a reader so the URL is usable
        try:
            perm = urllib.request.Request(
                f"https://www.googleapis.com/drive/v3/files/{fid}/permissions",
                data=json.dumps({"role": "reader", "type": "anyone"}).encode(),
                headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"})
            urllib.request.urlopen(perm, timeout=15).read()
        except Exception as e:
            print(f"[drive perm] {e}")
        return f"https://drive.google.com/uc?export=view&id={fid}"
    except Exception as e:
        print(f"[drive upload] {e}")
        return None

def send_telegram_bot_notification(chat_id, message_text, bot_token=None):
    tok = bot_token or TELEGRAM_TASKS_BOT_TOKEN
    if not tok or not chat_id:
        return False
    try:
        url = f"https://api.telegram.org/bot{tok}/sendMessage"
        payload = json.dumps({"chat_id": str(chat_id), "text": message_text, "parse_mode": "HTML"}).encode("utf-8")
        req = urllib.request.Request(url, data=payload, headers={"Content-Type": "application/json"})
        with urllib.request.urlopen(req, timeout=10) as resp:
            res = json.loads(resp.read().decode("utf-8"))
            return res.get("ok", False)
    except Exception as e:
        print(f"[Telegram Notification Exception] {e}")
        return False


