@app.route("/api/tasks/employees", methods=["GET", "POST"])
@auth_guard
def api_tasks_employees():
    _cid = current_client_id()
    if request.method == "POST":
        data = request.get_json() or {}
        emp_id = (data.get("employee_id") or "").strip() or f"EMP-{int(time.time()*1000)}"
        name = (data.get("name") or "").strip()
        role = data.get("role", "Employee")
        telegram_id = (data.get("telegram_id") or "").strip()
        email = (data.get("email") or "").strip()
        status = data.get("status", "active")

        if not name:
            return jsonify({"error": "اسم الموظف مطلوب"}), 400

        emps = get_client_employees(_cid)
        found = False
        for e in emps:
            if str(e.get("employee_id")) == str(emp_id):
                e.update({"name": name, "role": role, "telegram_id": telegram_id, "email": email, "status": status})
                found = True
                break
        if not found:
            emps.append({
                "employee_id": emp_id,
                "client_id": _cid,
                "name": name,
                "role": role,
                "telegram_id": telegram_id,
                "email": email,
                "status": status,
                "created_at": datetime.now(timezone.utc).isoformat()
            })
        save_client_employees(emps, _cid)
        return jsonify({"success": True, "employees": emps})

    # Employees are AGENCY-LEVEL (the real company team from the Google Sheet), shared
    # across all clients — same source the attendance/payroll bot uses. This is what makes
    # task assignment use the real people (عمر/فرح/ندى…) exactly like the n8n workflow.
    emps = []
    try:
        cfg = hr_config()
        for e in _gsheet_rows(cfg["sheet_id"], cfg["employees_gid"]):
            st = (e.get("status", "") or e.get("state", "")).lower()
            emps.append({
                "employee_id": e.get("employee_id", ""),
                "name": e.get("name", ""),
                "role": e.get("job", "") or "Employee",
                "telegram_id": e.get("telegram_id", ""),
                "status": "active" if st in ("active", "approved") else (st or "active"),
            })
    except Exception as _e:
        print(f"[tasks employees from sheet] {_e}")
    # Merge manually-added employees not present in the sheet — but ONLY real ones
    # (must have a telegram_id). This drops the old demo/role-name seed rows.
    seen = {str(x["employee_id"]) for x in emps if x.get("employee_id")}
    for e in get_client_employees(_cid):
        if str(e.get("employee_id")) not in seen and str(e.get("telegram_id") or "").strip():
            emps.append(e)
    return jsonify({"success": True, "employees": emps})


