@app.route("/api/plan/create", methods=["POST"])
@auth_guard
def api_plan_create():
    """Content team builds a plan IN the system: pick client + account manager, write
    the posts, and it's turned into tasks and sent to that AM. Returns a shareable link."""
    data = request.get_json() or {}
    client_id = (data.get("client_id") or "").strip()
    am_id = (data.get("am_employee_id") or "").strip()
    plan_text = (data.get("plan_text") or "").strip()
    if not client_id:
        return jsonify({"error": "اختر العميل"}), 400
    if not plan_text:
        return jsonify({"error": "اكتب البلان"}), 400

    tasks = get_client_tasks(client_id)
    max_num = 0
    for t in tasks:
        m = re.search(r'TASK-(\d+)', str(t.get("task_id") or ""))
        if m:
            max_num = max(max_num, int(m.group(1)))
    counter = max_num + 1
    _url_re = re.compile(r'https?://[^\s|]+')
    created = 0
    for block in _parse_plan_posts(plan_text):
        tagline, visual, cap, imgs, refs = "", "", [], [], []
        for ln in block:
            for u in _url_re.findall(ln):
                (imgs if ("drive.google" in u.lower() or u.lower().split("?")[0].endswith((".jpg", ".jpeg", ".png", ".webp", ".gif"))) else refs).append(u)
            c = _url_re.sub("", ln).strip()
            norm = c.replace("أ", "ا").replace("إ", "ا")
            if not c:
                continue
            if "تاج لاين" in norm or "تاجلاين" in norm or "tag line" in norm.lower():
                tagline = _after_colon(c)
            elif "التخيل" in norm or "تخيل" in norm or "الموشن" in norm or "التصميم" in norm:
                visual = _after_colon(c)
            elif c[0] in ("📍", "☎", "📞", "🏢") or c.startswith(("Banha", "El Sheikh", "(013)", "(+2)")):
                continue
            else:
                cap.append(c)
        title = (tagline or (cap[0] if cap else "مهمة")).lstrip("-•*✅✍️ ").strip()[:140]
        tasks.insert(0, {
            "task_id": f"TASK-{counter:04d}", "client_id": client_id, "title": title,
            "description": "\n".join(cap).strip() or title, "caption": "\n".join(cap).strip(),
            "status": "Pending AM Approval", "scheduled_start_date": "", "publish_date": "",
            "delivery_deadline": "", "am_id": am_id or "EMP-001", "assigned_employee_id": "",
            "assignee_name": "", "media_urls": imgs, "reference_links": refs,
            "content_data": {"post_type": "post", "tag_line": tagline or title, "visual_idea": visual},
            "graphic_data": {"idea": visual, "reference_images": imgs, "reference_links": refs},
            "created_by": current_username(), "created_at": datetime.now(timezone.utc).isoformat(),
        })
        counter += 1
        created += 1
    save_client_tasks(tasks, client_id)

    # notify the chosen account manager on Telegram
    if am_id:
        am = _sheet_emp(am_id)
        tg = str(am.get("telegram_id", "")).replace(".0", "").strip()
        if tg:
            send_telegram_bot_notification(tg,
                f"📋 <b>وصلك بلان جديد</b>\n🏢 {_client_name(client_id)}\n📝 عدد البوستات: {created}\n"
                f"👤 من: {current_user_rec().get('name') or current_username()}\n\nراجعه وحدّد المواعيد والإسناد من البوابة 🚀")

    # shareable read-only link (for showing the plan outside the system)
    shares = cache.get("plan_shares") or {}
    token = shares.get(client_id) or secrets.token_urlsafe(9)
    shares[client_id] = token
    cache["plan_shares"] = shares
    push_setting("meta_ai_plan_shares", shares)
    base = os.environ.get("PORTAL_URL", "https://metaaimoderator.vercel.app").rstrip("/")
    return jsonify({"ok": True, "created": created,
                    "share_url": f"{base}/share/plan/{client_id}?t={token}"})


@app.route("/share/plan/<client_id>", methods=["GET"])
def share_plan_view(client_id):
    """Public read-only plan view — send this link to anyone outside the system."""
    token = request.args.get("t", "")
    shares = cache.get("plan_shares") or {}
    if not token or shares.get(client_id) != token:
        return "<h3 style='font-family:sans-serif;text-align:center;margin-top:3rem'>🔒 رابط غير صالح</h3>", 401
    tasks = [t for t in get_client_tasks(client_id) if t.get("title")]
    cname = _client_name(client_id)
    cards = []
    for t in tasks:
        imgs = "".join(
            f'<a href="{u}" target="_blank"><img src="{u}" style="width:90px;height:90px;object-fit:cover;border-radius:8px;margin:2px"></a>'
            for u in (t.get("media_urls") or [])[:6])
        cap = (t.get("caption") or t.get("description") or "").replace("\n", "<br>")
        pub = t.get("publish_date") or "—"
        cards.append(
            f'<div style="background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:16px;margin:10px 0">'
            f'<div style="font-weight:800;font-size:15px;color:#0f172a">{t.get("title","")}</div>'
            f'<div style="color:#475569;font-size:13px;margin:6px 0;line-height:1.7">{cap}</div>'
            f'<div style="color:#2563eb;font-size:12px;font-weight:700">📅 النشر: {pub}</div>'
            f'<div style="margin-top:6px">{imgs}</div></div>')
    body = "".join(cards) or "<p style='text-align:center;color:#94a3b8'>لا توجد بوستات بعد</p>"
    return (f'<!doctype html><html dir="rtl" lang="ar"><head><meta charset="utf-8">'
            f'<meta name="viewport" content="width=device-width,initial-scale=1">'
            f'<title>بلان {cname}</title></head>'
            f'<body style="font-family:system-ui,sans-serif;background:#f8fafc;margin:0;padding:16px">'
            f'<div style="max-width:640px;margin:0 auto">'
            f'<h2 style="color:#0f172a">📋 بلان المحتوى — {cname}</h2>'
            f'<p style="color:#64748b;font-size:13px">عدد البوستات: {len(tasks)}</p>{body}'
            f'<p style="text-align:center;color:#cbd5e1;font-size:11px;margin-top:20px">Domya Meta Suite</p>'
            f'</div></body></html>')


@app.route("/api/tasks/<task_id>/references", methods=["POST"])
@require_manager
def api_task_add_reference(task_id):
    """AM adds a reference (image URL or link) to a task after receiving the plan."""
    t, cid = _find_task_any_client(task_id)
    if not t:
        return jsonify({"error": "المهمة غير موجودة"}), 404
    data = request.get_json() or {}
    url = (data.get("url") or "").strip()
    if not url:
        return jsonify({"error": "أدخل رابط"}), 400
    low = url.lower()
    is_img = ("drive.google" in low) or low.split("?")[0].endswith((".jpg", ".jpeg", ".png", ".webp", ".gif"))
    key = "media_urls" if is_img else "reference_links"
    t.setdefault(key, [])
    if url not in t[key]:
        t[key].append(url)
    save_client_tasks(get_client_tasks(cid), cid)
    return jsonify({"ok": True, "task": t})


@app.route("/api/tasks/<task_id>/upload", methods=["POST"])
@auth_guard
def api_task_upload_asset(task_id):
    """Upload a file (image/video) — auto-stored to Google Drive, link attached to the
    task. No need to paste a Drive link manually; everything lives in Drive."""
    t, cid = _find_task_any_client(task_id)
    if not t:
        return jsonify({"error": "المهمة غير موجودة"}), 404
    up = request.files.get("file") if request.files else None
    if not up or not up.filename:
        return jsonify({"error": "لم يتم اختيار ملف"}), 400
    raw = up.read()
    mime = up.mimetype or "application/octet-stream"
    safe = re.sub(r"[^\w.\-]+", "_", up.filename)[:80]
    name = f"{task_id}_{safe}"
    link = drive_upload_bytes(name, raw, mime)
    if not link:
        return jsonify({"error": "تعذّر الرفع على Drive"}), 500
    t["drive_link"] = link
    t.setdefault("media_urls", [])
    if link not in t["media_urls"]:
        t["media_urls"].append(link)
    t["media_type"] = "video" if mime.startswith("video") else "image"
    save_client_tasks(get_client_tasks(cid), cid)
    return jsonify({"ok": True, "drive_link": link, "task": t})


@app.route("/api/tasks/<task_id>/status", methods=["PUT", "POST"])
@auth_guard
def api_tasks_update_status(task_id):
    _cid = current_client_id()
    data = request.get_json() or {}
    new_status = data.get("status")
    emp_id = data.get("employee_id") or data.get("assigned_employee_id")
    notes = data.get("notes") or ""

    if not new_status:
        return jsonify({"error": "الحالة الجديدة مطلوبة"}), 400

    tasks = get_client_tasks(_cid)
    target_task = next((t for t in tasks if str(t.get("task_id")) == str(task_id)), None)
    if not target_task:
        return jsonify({"error": "المهمة غير موجودة"}), 404

    logs = get_client_task_logs(_cid)
    now_formatted = datetime.now(timezone.utc).strftime("%d/%m/%Y - %I:%M %p")

    target_task["status"] = new_status
    if emp_id:
        emps = get_client_employees(_cid)
        emp_obj = next((e for e in emps if str(e.get("employee_id")) == str(emp_id)), None)
        target_task["assigned_employee_id"] = emp_id
        if emp_obj:
            target_task["assignee_name"] = emp_obj.get("name", "")

    if notes:
        target_task["note"] = notes

    log_entry = next((l for l in logs if str(l.get("task_id")) == str(task_id) and l.get("status") in ("In Progress", "Assigned")), None)
    if not log_entry:
        log_entry = {
            "log_id": f"LOG-{task_id}-{int(time.time()*1000)}",
            "client_id": _cid,
            "task_id": task_id,
            "title": target_task.get("title", ""),
            "employee_name": target_task.get("assignee_name", "Unassigned"),
            "status": new_status,
            "start_time": now_formatted if new_status == "In Progress" else "",
            "end_time": now_formatted if new_status in ("Completed", "Awaiting AM Review") else "",
            "notes": notes
        }
        logs.insert(0, log_entry)
    else:
        log_entry["status"] = new_status
        if notes: log_entry["notes"] = notes
        if new_status == "In Progress" and not log_entry.get("start_time"):
            log_entry["start_time"] = now_formatted
        if new_status in ("Completed", "Awaiting AM Review"):
            log_entry["end_time"] = now_formatted

    save_client_tasks(tasks, _cid)
    save_client_task_logs(logs, _cid)
    return jsonify({"success": True, "task": target_task})


