# ============================================================
#  HR / Attendance / Payroll — reads the COMPANY Google Sheet
#  (agency-level, shared across all clients; admin/manager only)
#  n8n keeps running the automation; the app is the read dashboard.
# ============================================================
import csv as _csv
from io import StringIO as _StringIO

# Default company sheet (Domya). Override via /api/hr/config (stored in Supabase).
_HR_DEFAULTS = {
    "sheet_id": "1Y4i5wOm85xg6Umwph0i5-5SmssAdCy0uUlqUvzQwGj0",
    "employees_gid": "1158009464",
    "attendance_gid": "2023520809",
    "payroll_gid": "253719303",
}

def hr_config():
    cfg = cache.get("hr_sheet")
    if not isinstance(cfg, dict):
        cfg = {}
    out = dict(_HR_DEFAULTS)
    out.update({k: v for k, v in cfg.items() if v})
    return out

def _gsheet_rows(sheet_id, gid, timeout=12):
    """Fetch one tab of a link-viewable Google Sheet as a list of dict rows."""
    if not (sheet_id and gid):
        return []
    url = f"https://docs.google.com/spreadsheets/d/{sheet_id}/gviz/tq?tqx=out:csv&gid={gid}"
    try:
        r = requests.get(url, timeout=timeout)
        if r.status_code != 200 or "<html" in r.text[:80].lower():
            return []
        r.encoding = "utf-8"
        reader = _csv.DictReader(_StringIO(r.text))
        rows = []
        for row in reader:
            rows.append({(k or "").strip(): (v or "").strip() for k, v in row.items()})
        return rows
    except Exception as e:
        print(f"[HR sheet fetch] {e}")
        return []


@app.route("/api/hr/config", methods=["GET", "POST"])
@require_admin
def api_hr_config():
    global cache
    if request.method == "POST":
        data = request.get_json() or {}
        cur = cache.get("hr_sheet") if isinstance(cache.get("hr_sheet"), dict) else {}
        for k in ("sheet_id", "employees_gid", "attendance_gid", "payroll_gid"):
            if data.get(k) is not None:
                cur[k] = str(data.get(k)).strip()
        cache["hr_sheet"] = cur
        push_setting("meta_ai_hr_sheet", cur)
        return jsonify({"ok": True, "config": hr_config()})
    return jsonify({"config": hr_config()})


