@app.route("/api/hr/summary", methods=["GET"])
@require_admin
def api_hr_summary():
    """Live company summary computed from Employees + Attendance for a given month.
    Counts real worked days (excludes absent) and flags late — mirrors the payroll logic."""
    cfg = hr_config()
    emps = _gsheet_rows(cfg["sheet_id"], cfg["employees_gid"])
    att = _gsheet_rows(cfg["sheet_id"], cfg["attendance_gid"])
    month = (request.args.get("month") or datetime.now(timezone.utc).strftime("%Y-%m")).strip()
    out = []
    for e in emps:
        st = (e.get("status", "") or e.get("state", "")).lower()
        if st not in ("active", "approved"):
            continue
        eid = str(e.get("employee_id", ""))
        recs = [r for r in att if str(r.get("employee_id", "")) == eid and str(r.get("date", "")).startswith(month)]
        worked = [r for r in recs if str(r.get("status", r.get("action", ""))).strip().lower() not in ("absent", "غياب")]
        absents = len(recs) - len(worked)
        late = sum(1 for r in recs if str(r.get("status", "")).strip().lower() in ("late", "متأخر"))
        hours = 0.0
        for r in worked:
            try:
                hours += float(str(r.get("hours", "0")).replace(",", "") or 0)
            except Exception:
                pass
        try:
            per_day = float(str(e.get("salary_per_day", "0")).replace(",", "") or 0)
        except Exception:
            per_day = 0.0
        out.append({
            "employee_id": eid, "name": e.get("name", ""), "job": e.get("job", ""),
            "days": len(worked), "absent": absents, "late": late,
            "hours": round(hours, 2), "salary": round(len(worked) * per_day, 2),
        })
    out.sort(key=lambda x: x["salary"], reverse=True)
    total_salary = round(sum(x["salary"] for x in out), 2)
    return jsonify({"month": month, "summary": out, "employees": len(out), "total_salary": total_salary})



# ============================================================
#  Employee onboarding + self-service portal
#  - Admin/AM creates a portal account for each real company employee
#    (from the Google Sheet) and Telegram-DMs them their link + login.
#  - Employees sign in and see ONLY their own tasks + attendance.
# ============================================================
PORTAL_URL = os.environ.get("PORTAL_URL", "https://metaaimoderator.vercel.app")

def _emp_username(emp):
    # Stable, simple username = the employee id from the sheet.
    return str(emp.get("employee_id") or "").strip()

def _my_employee_id():
    """The sheet employee_id linked to the logged-in portal user (if any)."""
    return str(current_user_rec().get("employee_id") or "").strip()


@app.route("/api/employees/onboard", methods=["POST"])
@require_manager
def api_employees_onboard():
    """Create portal accounts for company employees and DM each their link + credentials
    via the tasks Telegram bot. Body: {employee_ids?: [...], resend?: bool}.
    If employee_ids omitted, onboards every sheet employee that has a telegram_id."""
    sync_from_supabase()
    data = request.get_json() or {}
    only = set(str(x) for x in (data.get("employee_ids") or []))
    cfg = hr_config()
    sheet_emps = list(_gsheet_rows(cfg["sheet_id"], cfg["employees_gid"]))
    # include manually-added employees (added from the dashboard) that aren't in the sheet
    _sheet_ids = {str(e.get("employee_id") or "").strip() for e in sheet_emps}
    for e in get_client_employees(current_client_id()):
        if str(e.get("employee_id") or "").strip() not in _sheet_ids:
            sheet_emps.append(e)
    results = []
    for e in sheet_emps:
        eid = str(e.get("employee_id") or "").strip()
        if not eid or (only and eid not in only):
            continue
        tg = str(e.get("telegram_id") or "").replace(".0", "").strip()
        name = e.get("name") or eid
        job = (e.get("job") or "").strip().lower()
        # Role by job: account managers → account_manager; everyone else (designers,
        # writers, editors, content…) → employee (sees ONLY their own tasks/attendance).
        is_am = ("account manager" in job or "أكونت" in job or "الحسابات" in job or eid.startswith("AM-"))
        role = "account_manager" if is_am else "employee"
        username = eid
        password = secrets.token_urlsafe(6)
        rec = USERS_DB.get(username) or {}
        # AMs see all clients by default so their board isn't empty (admin can narrow later).
        assigned = rec.get("assigned_clients", [])
        if is_am and not assigned:
            assigned = [c.get("id") for c in AGENCY_CLIENTS_STORE if c.get("id")]
        rec.update({
            "username": username, "password": hash_password(password), "role": role,
            "email": e.get("email", ""), "employee_id": eid, "name": name,
            "assigned_clients": assigned,
            "created_at": rec.get("created_at") or datetime.now(timezone.utc).isoformat(),
        })
        USERS_DB[username] = rec
        sent = False
        if tg:
            msg = (f"👋 أهلاً <b>{name}</b>\n\n"
                   f"ده حسابك على بوابة دوميه لمتابعة مهامك وحضورك:\n"
                   f"🔗 {PORTAL_URL}\n\n"
                   f"👤 اسم المستخدم: <code>{username}</code>\n"
                   f"🔑 كلمة المرور: <code>{password}</code>\n\n"
                   f"سجّل دخولك وهتلاقي المهام المسندة ليك 🚀")
            sent = bool(send_telegram_bot_notification(tg, msg))
        results.append({"employee_id": eid, "name": name, "role": role,
                        "username": username, "password": password if not tg else None,
                        "telegram_sent": sent, "has_telegram": bool(tg)})
    push_setting("meta_ai_users", USERS_DB)
    return jsonify({"ok": True, "onboarded": len(results), "results": results})


