@app.route("/api/tasks/<task_id>/assign", methods=["POST"])
@require_manager
def api_tasks_assign(task_id):
    """AM/admin assigns a task to a real employee and DMs them on Telegram."""
    sync_from_supabase()
    _cid = current_client_id()
    data = request.get_json() or {}
    emp_id = str(data.get("employee_id") or "").strip()
    if not emp_id:
        return jsonify({"error": "اختر موظفاً"}), 400
    cfg = hr_config()
    emp = next((e for e in _gsheet_rows(cfg["sheet_id"], cfg["employees_gid"])
                if str(e.get("employee_id")) == emp_id), None)
