@require_manager
def api_task_resend(task_id):
    """Re-send the interactive task card to the currently-assigned employee."""
    t, cid = _find_task_any_client(task_id)
    if not t:
        return jsonify({"error": "المهمة غير موجودة"}), 404
    if not t.get("assigned_employee_id"):
        return jsonify({"error": "المهمة مش مُسندة لحد"}), 400
    # refresh the display name from the sheet (older assigns stored just the id)
    nm = _sheet_emp(t.get("assigned_employee_id")).get("name", "")
    if nm and t.get("assignee_name") != nm:
        t["assignee_name"] = nm
        save_client_tasks(get_client_tasks(cid), cid)
    sent = bool(send_task_to_employee(t, cid))
    return jsonify({"ok": True, "telegram_sent": sent})


# ============================================================
#  Task lifecycle (native, mirrors the n8n workflow):
#  Assigned → In Progress → Awaiting AM Review → Completed / (rejected→Assigned)
#  Employees act on their OWN tasks; managers review. Telegram notifies each side.
# ============================================================
def _find_task_any_client(task_id):
    """Return (task, cid) for a task id across all clients, or (None, None)."""
    for t in (cache.get("tasks") or []):
        if isinstance(t, dict) and str(t.get("task_id")) == str(task_id):
            return t, t.get("client_id")
    return None, None

def _sheet_emp(emp_id):
    cfg = hr_config()
    return next((e for e in _gsheet_rows(cfg["sheet_id"], cfg["employees_gid"])
                 if str(e.get("employee_id")) == str(emp_id)), {}) or {}

def _client_name(cid):
    return next((c.get("name") for c in AGENCY_CLIENTS_STORE if c.get("id") == cid), cid)

def _owner_chat():
    return os.environ.get("OWNER_TELEGRAM_CHAT_ID", "1693828086")


@app.route("/api/me/tasks/<task_id>/start", methods=["POST"])
@auth_guard
def api_my_task_start(task_id):
    sync_from_supabase()
    eid = _my_employee_id()
    t, cid = _find_task_any_client(task_id)
    if not t:
        return jsonify({"error": "المهمة غير موجودة"}), 404
    if not is_manager() and str(t.get("assigned_employee_id")) != eid:
        return jsonify({"error": "دي مش مهمتك"}), 403
    t["status"] = "In Progress"
    t["started_at"] = datetime.now(timezone.utc).isoformat()
    ts = t.get("timer_state") or {"is_running": False, "elapsed_seconds": 0, "last_start": None}
    ts["is_running"] = True
    ts["last_start"] = t["started_at"]
    t["timer_state"] = ts
    save_client_tasks(get_client_tasks(cid), cid)  # persist (t is a live ref inside cache)
    return jsonify({"ok": True, "task": t})


def _notify_client_am(cid, msg):
    """DM the account manager(s) assigned to this client (via their sheet telegram_id).
    No owner spam — only the responsible AM is pinged."""
    for un, rec in list(USERS_DB.items()):
        if rec.get("role") == "account_manager" and cid in (rec.get("assigned_clients") or []):
            emp = _sheet_emp(rec.get("employee_id"))
            tg = str(emp.get("telegram_id", "")).replace(".0", "").strip()
            if tg:
                send_telegram_bot_notification(tg, msg)


@app.route("/api/me/tasks/<task_id>/submit", methods=["POST"])
@auth_guard
def api_my_task_submit(task_id):
    sync_from_supabase()
    eid = _my_employee_id()
    data = request.get_json() or {}
    notes = (data.get("notes") or "").strip()
    t, cid = _find_task_any_client(task_id)
    if not t:
        return jsonify({"error": "المهمة غير موجودة"}), 404
    if not is_manager() and str(t.get("assigned_employee_id")) != eid:
        return jsonify({"error": "دي مش مهمتك"}), 403
    # stop timer
    ts = t.get("timer_state") or {}
    if ts.get("is_running") and ts.get("last_start"):
        try:
            ts["elapsed_seconds"] = (ts.get("elapsed_seconds") or 0) + int(
                (datetime.now(timezone.utc) - datetime.fromisoformat(ts["last_start"])).total_seconds())
        except Exception:
            pass
    ts["is_running"] = False; ts["last_start"] = None
    t["timer_state"] = ts
    t["status"] = "Awaiting AM Review"
    t["notes"] = notes
    t["submitted_at"] = datetime.now(timezone.utc).isoformat()
    save_client_tasks(get_client_tasks(cid), cid)
    mins = round((ts.get("elapsed_seconds") or 0) / 60, 1)
    # ping ONLY the client's account manager (it also shows in their web board).
    _notify_client_am(cid,
        f"📥 <b>مهمة جاهزة للمراجعة</b>\n👤 {t.get('assignee_name','')}\n📝 {t.get('title','')}\n"
        f"🏢 {_client_name(cid)}\n⏱️ الوقت: {mins} دقيقة\n📝 ملاحظات: {notes or '—'}")
    return jsonify({"ok": True, "task": t, "minutes": mins})


@app.route("/api/tasks/<task_id>/review", methods=["POST"])
@require_manager
def api_task_review(task_id):
    """AM review of a submitted task, three outcomes:
      • reject  → back to the same employee for fixes.
      • forward → hand off to the NEXT employee in the chain (next_employee_id).
      • finalize → mark Completed AND auto-create a scheduled post in the Scheduler.
    """
    sync_from_supabase()
    data = request.get_json() or {}
    action = (data.get("action") or "approve").lower()
    review_note = (data.get("note") or "").strip()
    next_emp_id = str(data.get("next_employee_id") or "").strip()
    t, cid = _find_task_any_client(task_id)
    if not t:
        return jsonify({"error": "المهمة غير موجودة"}), 404
    cur_emp = _sheet_emp(t.get("assigned_employee_id"))
    cur_tg = str(cur_emp.get("telegram_id", "")).replace(".0", "").strip()
    t["review_note"] = review_note
    scheduled = None

    if action in ("reject", "return"):
        t["status"] = "Assigned"
        if cur_tg:
            send_telegram_bot_notification(cur_tg,
                f"🔄 <b>محتاج تعديل</b>\n📝 {t.get('title','')}\n🏢 {_client_name(cid)}\n📝 {review_note or 'راجع الملاحظات'}")
    elif next_emp_id:
        # Forward to the next person in the chain.
        nxt = _sheet_emp(next_emp_id)
        t["assigned_employee_id"] = next_emp_id
        t["assignee_name"] = nxt.get("name", next_emp_id)
        t["status"] = "Assigned"
        t["stage_history"] = (t.get("stage_history") or []) + [{
            "employee_id": t.get("assigned_employee_id"), "at": datetime.now(timezone.utc).isoformat()}]
        ntg = str(nxt.get("telegram_id", "")).replace(".0", "").strip()
        if ntg:
            send_telegram_bot_notification(ntg,
                f"📋 <b>مهمة وصلتلك</b>\n👤 {nxt.get('name','')}\n📝 {t.get('title','')}\n"
                f"🏢 {_client_name(cid)}\n⏰ تسليم: {t.get('delivery_deadline','-')}\nابدأ من البوابة 🚀")
    else:
        # Finalize → Completed → auto-create a scheduled post from the task data.
        t["status"] = "Completed"
        t["completed_at"] = datetime.now(timezone.utc).isoformat()
        try:
            urls = t.get("media_urls") or ([t.get("drive_link")] if t.get("drive_link") else [])
            post = {
                "id": f"post-{int(time.time()*1000)}",
                "client_id": cid,
                "caption": t.get("caption") or t.get("description") or t.get("title", ""),
                "target": t.get("target", "fb"),
                "media_type": (t.get("media_type") or "image").lower(),
                "drive_link": t.get("drive_link", ""),
                "media_urls": [u for u in urls if u],
                "media_url": drive_to_direct(urls[0]) if urls and urls[0] else "",
                "date": t.get("publish_date", ""),
                "time": t.get("publish_time", "10:00"),
                "scheduled_at": _local_to_utc_iso(t.get("publish_date", ""), t.get("publish_time", "10:00")),
                "status": "pending",
                "from_task": t.get("task_id"),
            }
            IN_MEMORY_POSTS.insert(0, post)
            push_setting("meta_ai_scheduled_posts", IN_MEMORY_POSTS)
            t["scheduled_post_id"] = post["id"]
            scheduled = post
        except Exception as _e:
            print(f"[task→schedule] {_e}")
        if cur_tg:
            send_telegram_bot_notification(cur_tg,
                f"✅ <b>تم اعتماد مهمتك واتجدولت للنشر</b>\n📝 {t.get('title','')}\n🏢 {_client_name(cid)}\n"
                + (f"📝 {review_note}" if review_note else "شغل جميل 👏"))
    save_client_tasks(get_client_tasks(cid), cid)
    return jsonify({"ok": True, "task": t, "scheduled": scheduled})


# ============================================================
#  Native Attendance Telegram Bot (replaces the n8n workflow)
#  Handles check-in / check-out (geofenced), status, absent, and
#  self-onboarding + owner approval — all inside our system.
#  Writes attendance/employees to the SAME Google Sheet the app reads.
# ============================================================
import urllib.request as _urlreq
import urllib.error as _urlerr

ATT_GEOFENCE_M = float(os.environ.get("ATT_GEOFENCE_M", "50"))
ATT_DEFAULT_LAT = float(os.environ.get("ATT_DEFAULT_LAT", "30.46977"))
ATT_DEFAULT_LON = float(os.environ.get("ATT_DEFAULT_LON", "31.18002"))
ATT_LATE_AFTER = os.environ.get("ATT_LATE_AFTER", "11:01:00")  # HH:MM:SS
_SHEET_TITLE_CACHE = {}

def _att_bot_token():
    return os.environ.get("TELEGRAM_ATTENDANCE_BOT_TOKEN", "")

def _cairo_now():
    """Current time in Africa/Cairo, DST-aware (Egypt uses UTC+3 in summer)."""
    try:
        from zoneinfo import ZoneInfo
        return datetime.now(ZoneInfo("Africa/Cairo"))
    except Exception:
        # fallback: fixed offset from env (default +3, current Egypt summer time)
        return datetime.now(timezone.utc) + timedelta(hours=float(os.environ.get("CAIRO_TZ_OFFSET", "3")))

def _cairo_now_parts():
    """Return (date 'YYYY-MM-DD', time 'HH:MM:SS') in Africa/Cairo, DST-aware."""
    now = _cairo_now()
    return now.strftime("%Y-%m-%d"), now.strftime("%H:%M:%S")

def _haversine_m(lat1, lon1, lat2, lon2):
    import math
    R = 6371000.0
    dlat = math.radians(lat2 - lat1)
    dlon = math.radians(lon2 - lon1)
    a = (math.sin(dlat/2)**2 + math.cos(math.radians(lat1))*math.cos(math.radians(lat2))*math.sin(dlon/2)**2)
    return int(round(R * 2 * math.atan2(math.sqrt(a), math.sqrt(1-a))))

# ---- Telegram send helpers (attendance bot) ----
def _att_send(chat_id, text, keyboard=None, inline=None):
    tok = _att_bot_token()
    if not tok or not chat_id:
        return False
    payload = {"chat_id": str(chat_id), "text": text, "parse_mode": "HTML"}
    if keyboard is not None:
        payload["reply_markup"] = {"keyboard": keyboard, "resize_keyboard": True}
    if inline is not None:
        payload["reply_markup"] = {"inline_keyboard": inline}
    try:
        req = _urlreq.Request(f"https://api.telegram.org/bot{tok}/sendMessage",
                              data=json.dumps(payload).encode("utf-8"),
                              headers={"Content-Type": "application/json"})
        return json.loads(_urlreq.urlopen(req, timeout=12).read()).get("ok", False)
    except Exception as e:
        print(f"[att send] {e}")
        return False

def _att_answer_callback(cb_id, text=""):
    tok = _att_bot_token()
    try:
        req = _urlreq.Request(f"https://api.telegram.org/bot{tok}/answerCallbackQuery",
                              data=json.dumps({"callback_query_id": cb_id, "text": text}).encode("utf-8"),
                              headers={"Content-Type": "application/json"})
        _urlreq.urlopen(req, timeout=10).read()
    except Exception as e:
        print(f"[att answer cb] {e}")

def _att_delete_message(chat_id, message_id):
    """Delete a message (used to wipe the shared location for privacy). Bots can
    delete incoming messages in private chats within 48h."""
    tok = _att_bot_token()
    if not tok or not chat_id or not message_id:
        return False
    try:
        req = _urlreq.Request(f"https://api.telegram.org/bot{tok}/deleteMessage",
                              data=json.dumps({"chat_id": str(chat_id), "message_id": message_id}).encode("utf-8"),
                              headers={"Content-Type": "application/json"})
        return json.loads(_urlreq.urlopen(req, timeout=10).read()).get("ok", False)
    except Exception as e:
        print(f"[att delete msg] {e}")
        return False

def _att_menu():
    return [["📍 تسجيل حضور", "🚪 تسجيل انصراف"], ["📊 حالتي اليوم", "🚫 تسجيل غياب"]]

# ---- Google Sheets read/write (uses the Drive OAuth token) ----
def _sheet_title_for_gid(spreadsheet_id, gid):
    key = f"{spreadsheet_id}:{gid}"
    if key in _SHEET_TITLE_CACHE:
        return _SHEET_TITLE_CACHE[key]
    token = get_google_oauth_access_token()
    if not token:
        return None
    try:
        req = _urlreq.Request(
            f"https://sheets.googleapis.com/v4/spreadsheets/{spreadsheet_id}?fields=sheets.properties",
            headers={"Authorization": f"Bearer {token}"})
        meta = json.loads(_urlreq.urlopen(req, timeout=15).read())
        for s in meta.get("sheets", []):
            props = s.get("properties", {})
            if str(props.get("sheetId")) == str(gid):
                title = props.get("title")
                _SHEET_TITLE_CACHE[key] = title
                return title
    except Exception as e:
        print(f"[sheet title] {e}")
    return None

def _sheets_append(spreadsheet_id, gid, header_order, row_dict):
    """Write a new row at the first empty row, aligned to the sheet's ACTUAL header.
    Uses values.update at a fixed A{row} anchor — NOT values.append, whose table
    detection mis-places rows when the header has trailing empty columns."""
    token = get_google_oauth_access_token()
    title = _sheet_title_for_gid(spreadsheet_id, gid)
    if not token or not title:
        return False
    header, rows = _sheets_get_all(spreadsheet_id, gid)
    if not header:
        header = header_order
    # align values to the real header columns (fills trailing empty header cols with "")
    line = [row_dict.get(h, "") for h in header]
    rownum = len(rows) + 2  # header is row 1
    try:
        url = (f"https://sheets.googleapis.com/v4/spreadsheets/{spreadsheet_id}/values/"
               f"{urllib.parse.quote(title)}!A{rownum}?valueInputOption=USER_ENTERED")
        req = _urlreq.Request(url, data=json.dumps({"values": [line]}).encode("utf-8"),
                              headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
                              method="PUT")
        _urlreq.urlopen(req, timeout=15).read()
        return True
    except Exception as e:
        print(f"[sheets append] {e}")
        return False

def _sheets_get_all(spreadsheet_id, gid):
    """Return (header_list, rows_as_lists) for the whole tab."""
    token = get_google_oauth_access_token()
    title = _sheet_title_for_gid(spreadsheet_id, gid)
    if not token or not title:
        return [], []
    try:
        url = f"https://sheets.googleapis.com/v4/spreadsheets/{spreadsheet_id}/values/{urllib.parse.quote(title)}!A:Z"
        req = _urlreq.Request(url, headers={"Authorization": f"Bearer {token}"})
        data = json.loads(_urlreq.urlopen(req, timeout=15).read())
        vals = data.get("values", [])
        if not vals:
            return [], []
        return vals[0], vals[1:]
    except Exception as e:
        print(f"[sheets get] {e}")
        return [], []

def _sheets_update_match(spreadsheet_id, gid, match, updates):
    """Find the first data row where all match{} cols equal, apply updates{}, write it back.
    Returns True on success."""
    token = get_google_oauth_access_token()
    title = _sheet_title_for_gid(spreadsheet_id, gid)
    if not token or not title:
        return False
    header, rows = _sheets_get_all(spreadsheet_id, gid)
    if not header:
        return False
    idx = {h: i for i, h in enumerate(header)}
    for r_i, row in enumerate(rows):
        ok = True
        for k, v in match.items():
            cur = row[idx[k]] if k in idx and idx[k] < len(row) else ""
            if str(cur).strip() != str(v).strip():
                ok = False
                break
        if not ok:
            continue
        # pad row to header length
        row = list(row) + [""] * (len(header) - len(row))
        for k, v in updates.items():
            if k in idx:
                row[idx[k]] = v
        rownum = r_i + 2  # 1-based + header
        try:
            url = (f"https://sheets.googleapis.com/v4/spreadsheets/{spreadsheet_id}/values/"
                   f"{urllib.parse.quote(title)}!A{rownum}?valueInputOption=USER_ENTERED")
            req = _urlreq.Request(url, data=json.dumps({"values": [row]}).encode("utf-8"),
                                  headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"},
                                  method="PUT")
            _urlreq.urlopen(req, timeout=15).read()
            return True
        except Exception as e:
            print(f"[sheets update] {e}")
            return False
    return False

# ---- Employee lookup by telegram id ----
def _att_emp_by_tg(tg_id):
    cfg = hr_config()
    tg = str(tg_id).replace(".0", "").strip()
    # Read FRESH via the Sheets API (gviz CSV lags a few minutes behind writes,
    # which would break the multi-step onboarding). Fall back to gviz on error.
    try:
        header, rows = _sheets_get_all(cfg["sheet_id"], cfg["employees_gid"])
        if header:
            idx = {h: i for i, h in enumerate(header)}
            ti = idx.get("telegram_id")
            for row in rows:
                if ti is not None and ti < len(row) and str(row[ti]).replace(".0", "").strip() == tg:
                    return {h: (row[i] if i < len(row) else "") for h, i in idx.items()}
            return None  # fresh read succeeded, not found
    except Exception as e:
        print(f"[att emp fresh] {e}")
    for e in _gsheet_rows(cfg["sheet_id"], cfg["employees_gid"]):
        if str(e.get("telegram_id", "")).replace(".0", "").strip() == tg:
            return e
    return None

def _att_today_records(emp_id, today):
    """Read TODAY's attendance rows for an employee — FRESH via Sheets API (gviz lags
    minutes and would cause a duplicate check-in row instead of a checkout update)."""
    cfg = hr_config()
    out = []
    try:
        header, rows = _sheets_get_all(cfg["sheet_id"], cfg["attendance_gid"])
        if header:
            idx = {h: i for i, h in enumerate(header)}
            ei, di = idx.get("employee_id"), idx.get("date")
            for row in rows:
                eid = row[ei] if ei is not None and ei < len(row) else ""
                dt = row[di] if di is not None and di < len(row) else ""
                if str(eid).strip() == str(emp_id).strip() and str(dt)[:10] == today:
                    out.append({h: (row[i] if i < len(row) else "") for h, i in idx.items()})
            return out
    except Exception as e:
        print(f"[att today fresh] {e}")
    for r in _gsheet_rows(cfg["sheet_id"], cfg["attendance_gid"]):
        if str(r.get("employee_id", "")).strip() == str(emp_id).strip() and str(r.get("date", ""))[:10] == today:
            out.append(r)
    return out

# ---- Core flows ----
def _att_handle_location(emp, chat_id, loc):
    cfg = hr_config()
    today, now_t = _cairo_now_parts()
    try:
        clat = float(emp.get("latitude") or ATT_DEFAULT_LAT)
        clon = float(emp.get("longitude") or ATT_DEFAULT_LON)
    except Exception:
        clat, clon = ATT_DEFAULT_LAT, ATT_DEFAULT_LON
    dist = _haversine_m(float(loc["latitude"]), float(loc["longitude"]), clat, clon)
    if dist > ATT_GEOFENCE_M:
        _att_send(chat_id, f"❌ <b>أنت خارج نطاق الشركة</b>\n📍 المسافة: <code>{dist} متر</code>\nلازم تكون في مكان العمل عشان تسجّل.", keyboard=_att_menu())
        return
    recs = _att_today_records(emp.get("employee_id"), today)
    has_in = any(str(r.get("checkin_time", "")).strip() not in ("", "0") for r in recs)
    has_out = any(str(r.get("checkout_time", "")).strip() not in ("", "0") for r in recs)
    emp_id = str(emp.get("employee_id", "")).strip()
    fdist = f"{dist} متر" if dist < 1000 else f"{dist/1000:.2f} كم"
    if has_in and has_out:
        _att_send(chat_id, "✅ سجّلت حضورك وانصرافك النهاردة خلاص. شكراً!", keyboard=_att_menu())
        return
    if not has_in:
        status = "متأخر" if now_t >= ATT_LATE_AFTER else "حاضر"
        ok = _sheets_append(cfg["sheet_id"], cfg["attendance_gid"],
            ["employee_id", "date", "name", "checkin_time", "checkout_time", "hours", "latitude", "longitude", "distance", "status"],
            {"employee_id": emp_id, "date": today, "name": emp.get("name", ""), "checkin_time": now_t,
             "checkout_time": "", "hours": "", "latitude": loc["latitude"], "longitude": loc["longitude"],
             "distance": f"{dist}m", "status": status})
        if ok:
            emoji = "⚠️" if status == "متأخر" else "✅"
            _att_send(chat_id, f"🟢 <b>تم تسجيل الحضور بنجاح!</b>\n👤 {emp.get('name','')}\n📅 {today}\n⏰ {now_t}\n{emoji} الحالة: {status}\n📍 {fdist}", keyboard=_att_menu())
            _att_notify_owner(f"🟢 حضور: {emp.get('name','')} — {now_t} ({status})")
        else:
            _att_send(chat_id, "⚠️ حصل خطأ في حفظ الحضور. حاول تاني.", keyboard=_att_menu())
    else:
        # checkout
        rec = next((r for r in recs if str(r.get("checkin_time", "")).strip() not in ("", "0")), {})
        cin = str(rec.get("checkin_time", "")).strip()
        hours = "0"
        try:
            ih, im = int(cin.split(":")[0]), int(cin.split(":")[1])
            oh, om = int(now_t.split(":")[0]), int(now_t.split(":")[1])
            hours = f"{(oh*60+om-ih*60-im)/60:.2f}"
        except Exception:
            pass
        ok = _sheets_update_match(cfg["sheet_id"], cfg["attendance_gid"],
            {"employee_id": emp_id, "date": today},
            {"checkout_time": now_t, "hours": hours})
        if ok:
            _att_send(chat_id, f"🔴 <b>تم تسجيل الانصراف بنجاح!</b>\n👤 {emp.get('name','')}\n📅 {today}\n⏰ {now_t}\n⌛ ساعات العمل: {hours}\n📍 {fdist}", keyboard=_att_menu())
            _att_notify_owner(f"🔴 انصراف: {emp.get('name','')} — {now_t} ({hours}h)")
        else:
            _att_send(chat_id, "⚠️ حصل خطأ في حفظ الانصراف. حاول تاني.", keyboard=_att_menu())

def _att_notify_owner(msg):
    _att_send(_owner_chat(), msg)

def _att_status(emp, chat_id):
    today, _ = _cairo_now_parts()
    recs = _att_today_records(emp.get("employee_id"), today)
    rec = recs[0] if recs else None
    txt = f"📊 <b>تقرير حالتك ({today})</b>\n\n👤 {emp.get('name','')}\n"
    if not rec:
        txt += "📌 الحالة: ❌ لم تسجّل الحضور بعد."
    else:
        st = str(rec.get("status", "")).lower()
        badge = "🚫 غياب" if st in ("غياب", "absent") else "⚠️ متأخر" if st in ("متأخر", "late") else "✅ في الوقت"
        txt += (f"📥 الحضور: {rec.get('checkin_time') or '-'}\n"
                f"📤 الانصراف: {rec.get('checkout_time') or 'لم يُسجل بعد'}\n"
                f"⏱️ ساعات العمل: {rec.get('hours') or '0'}\n📌 الحالة: {badge}")
    _att_send(chat_id, txt, keyboard=_att_menu())

def _att_absent(emp, chat_id):
    cfg = hr_config()
    today, _ = _cairo_now_parts()
    recs = _att_today_records(emp.get("employee_id"), today)
    if recs:
        _att_send(chat_id, "📌 عندك سجل بالفعل النهاردة، مش هينفع تسجّل غياب.", keyboard=_att_menu())
        return
    ok = _sheets_append(cfg["sheet_id"], cfg["attendance_gid"],
        ["employee_id", "date", "name", "checkin_time", "checkout_time", "hours", "latitude", "longitude", "distance", "status"],
        {"employee_id": str(emp.get("employee_id", "")).strip(), "date": today, "name": emp.get("name", ""),
         "checkin_time": "", "checkout_time": "", "hours": "0", "latitude": "0", "longitude": "0", "distance": "0", "status": "غياب"})
    _att_send(chat_id, "🚫 تم تسجيل غيابك لليوم." if ok else "⚠️ خطأ في التسجيل.", keyboard=_att_menu())

# ---- Onboarding (self-registration) ----
def _att_onboard(msg, tg_id, text, chat_id):
    cfg = hr_config()
    emp = _att_emp_by_tg(tg_id)
    status = str((emp or {}).get("status", "")).strip().lower()
    # Already active → only greet on /start; otherwise let the caller handle commands.
    if emp and status in ("active", "approved"):
        if text == "/start":
            _att_send(chat_id, f"👋 أهلاً {emp.get('name','')}! حسابك مفعّل. اختر من القائمة:", keyboard=_att_menu())
            return True
        return False
    # Unknown user → ANY first message starts registration (not only /start).
    if not emp:
        eid = f"EMP-{str(tg_id)[-4:]}-{str(int(datetime.now(timezone.utc).timestamp()))[-4:]}"
        _sheets_append(cfg["sheet_id"], cfg["employees_gid"],
            ["employee_id", "name", "telegram_id", "salary_per_day", "status", "job", "state"],
            {"employee_id": eid, "telegram_id": str(tg_id), "status": "awaiting name", "state": "awaiting name"})
        _att_send(chat_id, "👋 أهلاً بك في نظام دوميه!\nلتسجيلك، اكتب <b>اسمك الكامل</b>:")
        return True
    # In-progress onboarding — /start just re-asks the current step.
    if text == "/start":
        if status == "awaiting name":
            _att_send(chat_id, "اكتب <b>اسمك الكامل</b>:")
        elif status == "awaiting job":
            _att_send(chat_id, "اكتب <b>وظيفتك</b>:")
        else:
            _att_send(chat_id, "⏳ حسابك تحت المراجعة من الإدارة.")
        return True
    if status == "awaiting name":
        _sheets_update_match(cfg["sheet_id"], cfg["employees_gid"], {"telegram_id": str(tg_id)},
                             {"name": text, "status": "awaiting job", "state": "awaiting job"})
        _att_send(chat_id, f"تمام يا {text} 👍\nدلوقتي اكتب <b>وظيفتك</b> (مصمم / كاتب / مونتير...):")
        return True
    if status == "awaiting job":
        _sheets_update_match(cfg["sheet_id"], cfg["employees_gid"], {"telegram_id": str(tg_id)},
                             {"job": text, "status": "pending approval", "state": "pending approval"})
        _att_send(chat_id, "✅ تم استلام بياناتك! حسابك تحت مراجعة الإدارة وهيتفعّل قريب.")
        # notify owner with approve/reject buttons
        nm = (emp.get("name") or "")
        _att_send(_owner_chat(),
            f"🆕 <b>طلب تسجيل موظف جديد</b>\n👤 الاسم: {nm}\n💼 الوظيفة: {text}\n🆔 تليجرام ID: {tg_id}\n🔑 كود الموظف: {emp.get('employee_id','')}",
            inline=[[{"text": "✅ قبول", "callback_data": f"owner_approve_{tg_id}"},
                     {"text": "❌ رفض", "callback_data": f"owner_reject_{tg_id}"}]])
        return True
    return False

def _att_owner_callback(cbq):
    cfg = hr_config()
    data = str(cbq.get("data", ""))
    cb_id = cbq.get("id")
    # Only the owner (محمد سعيد) may approve/reject. Extra approvers via env
    # OWNER_APPROVERS (comma-separated chat ids). Anyone else is ignored.
    presser = str((cbq.get("from") or {}).get("id", "")).strip()
    allowed = {str(_owner_chat()).strip()}
    allowed |= {x.strip() for x in os.environ.get("OWNER_APPROVERS", "").split(",") if x.strip()}
    if presser not in allowed:
        print(f"[att approval blocked] presser={presser} not in {allowed}")
        _att_answer_callback(cb_id, "غير مصرح لك بالموافقة")
        return
    approve = data.startswith("owner_approve_")
    tg_id = data.replace("owner_approve_", "").replace("owner_reject_", "").strip()
    emp = _att_emp_by_tg(tg_id)
    if approve:
        _sheets_update_match(cfg["sheet_id"], cfg["employees_gid"], {"telegram_id": str(tg_id)},
                             {"status": "active", "state": "active"})
        _att_answer_callback(cb_id, "تم القبول")
        _att_send(tg_id, "🎉 <b>تم تفعيل حسابك!</b> تقدر تسجّل حضورك دلوقتي.", keyboard=_att_menu())
    else:
        _sheets_update_match(cfg["sheet_id"], cfg["employees_gid"], {"telegram_id": str(tg_id)},
                             {"status": "rejected", "state": "rejected"})
        _att_answer_callback(cb_id, "تم الرفض")
        _att_send(tg_id, "❌ نأسف، تم رفض طلب تسجيلك. تواصل مع الإدارة.")

@app.route("/api/telegram/attendance", methods=["POST"])
def telegram_attendance_webhook():
    # Mandatory shared-secret check — Telegram sends it as a header (set via setWebhook).
    # Fail CLOSED: if the secret isn't configured, or the header doesn't match, reject.
    secret = os.environ.get("TELEGRAM_WEBHOOK_SECRET", "")
    if not secret or request.headers.get("X-Telegram-Bot-Api-Secret-Token", "") != secret:
        return jsonify({"ok": False}), 401
    try:
        update = request.get_json(force=True, silent=True) or {}
    except Exception:
        update = {}
    try:
        # owner inline approve/reject
        if update.get("callback_query"):
            _att_owner_callback(update["callback_query"])
            return jsonify({"ok": True})
        msg = update.get("message") or update.get("edited_message") or {}
        chat_id = str((msg.get("chat") or {}).get("id", ""))
        tg_id = str((msg.get("from") or {}).get("id", ""))
        text = (msg.get("text") or "").strip()
        loc = msg.get("location")

        emp = _att_emp_by_tg(tg_id)
        emp_status = str((emp or {}).get("status", "")).strip().lower()
        active = bool(emp) and emp_status in ("active", "approved")
        kind = "location" if loc else ("callback" if update.get("callback_query") else "text")
        print(f"[att in] tg={tg_id} kind={kind} text={text[:40]!r} "
              f"emp={'Y' if emp else 'N'} status={emp_status or '-'} active={active}")

        # Onboarding path: unknown user (any message), in-progress onboarding, or /start.
        if (not emp) or (not active) or text == "/start":
            handled = _att_onboard(msg, tg_id, text, chat_id)
            if handled is not False:
                return jsonify({"ok": True})

        if not emp:
            _att_send(chat_id, "👋 أهلاً بك! اكتب /start لتسجيل حسابك في نظام دوميه.")
            return jsonify({"ok": True})
        if not active:
            _att_send(chat_id, "⏳ حسابك تحت المراجعة من الإدارة.")
            return jsonify({"ok": True})

        if loc:
            msg_id = msg.get("message_id")
            msg_date = max(int(msg.get("date") or 0), int(msg.get("edit_date") or 0))
            now_ts = int(datetime.now(timezone.utc).timestamp())
            max_age = int(os.environ.get("ATT_LOC_MAX_AGE", "150"))  # seconds
            # 1) freshness / anti-spoof: reject an old or replayed location pin
            if msg_date and (now_ts - msg_date) > max_age:
                _att_delete_message(chat_id, msg_id)
                _att_send(chat_id, "⚠️ الموقع ده قديم. اضغط 📎 ثم Location واختر <b>«إرسال موقعي الحالي»</b> (مش موقع محفوظ أو محوّل).", keyboard=_att_menu())
                return jsonify({"ok": True})
            # 2) reject forwarded locations (a location relayed from elsewhere)
            if msg.get("forward_date") or msg.get("forward_from") or msg.get("forward_origin"):
                _att_delete_message(chat_id, msg_id)
                _att_send(chat_id, "⚠️ مينفعش موقع محوّل (Forwarded). ابعت موقعك الحالي المباشر.", keyboard=_att_menu())
                return jsonify({"ok": True})
            # 3) process, then wipe the shared location for privacy
            _att_handle_location(emp, chat_id, loc)
            _att_delete_message(chat_id, msg_id)
        elif text == "📍 تسجيل حضور":
            _att_send(chat_id, "📍 ابعت موقعك الجغرافي (Location) عشان أسجّل حضورك.",
                      keyboard=[[{"text": "📍 إرسال موقعي", "request_location": True}]])
        elif text == "🚪 تسجيل انصراف":
            _att_send(chat_id, "📍 ابعت موقعك الجغرافي (Location) عشان أسجّل انصرافك.",
                      keyboard=[[{"text": "📍 إرسال موقعي", "request_location": True}]])
        elif text == "📊 حالتي اليوم":
            _att_status(emp, chat_id)
        elif text == "🚫 تسجيل غياب":
            _att_absent(emp, chat_id)
        else:
            _att_send(chat_id, f"👋 أهلاً {emp.get('name','')}! اختر من القائمة:", keyboard=_att_menu())
        return jsonify({"ok": True})
    except Exception as e:
        print(f"[att webhook] {e}")
        return jsonify({"ok": True})  # always 200 so Telegram doesn't retry-storm


def _diag_ok():
    """Auth for diagnostic/maintenance endpoints: admin session OR the CRON_SECRET
    supplied in the X-Diag-Key HEADER (never a query param, which would be logged)."""
    _cs = os.environ.get("CRON_SECRET", "")
    if _cs and request.headers.get("X-Diag-Key", "") == _cs:
        return True
    return ("uid" in session) and is_admin()


@app.route("/api/telegram/attendance/welcome", methods=["POST"])
def att_welcome_broadcast():
    """Send a welcome message via the attendance bot to every active employee who
    has a telegram_id. Auth: admin session OR X-Diag-Key header."""
    if not _diag_ok():
        return jsonify({"error": "Unauthorized"}), 401
    cfg = hr_config()
    custom = (request.get_json(silent=True) or {}).get("message", "").strip()
    results = {"sent": 0, "skipped": 0, "total": 0}
    for e in _gsheet_rows(cfg["sheet_id"], cfg["employees_gid"]):
        name = (e.get("name") or "").strip()
        tg = str(e.get("telegram_id", "")).replace(".0", "").strip()
        status = str(e.get("status", "")).strip().lower()
        if not name or not tg or status not in ("active", "approved"):
            results["skipped"] += 1
            continue
        results["total"] += 1
        msg = custom or (
            f"👋 أهلاً <b>{name}</b> في نظام دوميه!\n\n"
            f"من هنا تقدر:\n"
            f"📍 تسجيل حضورك وانصرافك بموقعك\n"
            f"📊 متابعة حالتك اليومية\n"
            f"🚫 تسجيل غيابك\n\n"
            f"اختر من القائمة بالأسفل للبدء 👇")
        if _att_send(tg, msg, keyboard=_att_menu()):
            results["sent"] += 1
    return jsonify({"ok": True, **results})


@app.route("/api/hr/cleanup", methods=["POST"])
def hr_cleanup_blank_rows():
    """Delete corrupted employee rows where column A (employee_id) is empty but the
    row still holds stray data (from the old mis-aligned append). Auth: admin OR ?key=CRON_SECRET."""
    if not _diag_ok():
        return jsonify({"error": "Unauthorized"}), 401
    cfg = hr_config()
    sid, gid = cfg["sheet_id"], cfg["employees_gid"]
    token = get_google_oauth_access_token()
    header, rows = _sheets_get_all(sid, gid)
    if not token or not header:
        return jsonify({"error": "no token or empty sheet"}), 400
    # rows[i] -> sheet row index (0-based) = i + 1 (header is index 0)
    bad = []
    for i, row in enumerate(rows):
        col_a = (row[0].strip() if len(row) > 0 else "")
        has_data = any((c or "").strip() for c in row)
        if not col_a and has_data:
            bad.append(i + 1)  # 0-based sheet row index
    if not bad:
        return jsonify({"ok": True, "removed": 0})
    # delete bottom-up so indices stay valid
    requests_body = [{"deleteDimension": {"range": {
        "sheetId": int(gid), "dimension": "ROWS", "startIndex": idx, "endIndex": idx + 1}}}
        for idx in sorted(bad, reverse=True)]
    try:
        req = urllib.request.Request(
            f"https://sheets.googleapis.com/v4/spreadsheets/{sid}:batchUpdate",
            data=json.dumps({"requests": requests_body}).encode("utf-8"),
            headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"})
        urllib.request.urlopen(req, timeout=20).read()
        return jsonify({"ok": True, "removed": len(bad)})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)[:200]}), 500


@app.route("/api/telegram/bots", methods=["GET"])
def telegram_bots_info():
    """List the configured Telegram bots (username + role). Auth: admin OR ?key=CRON_SECRET."""
    if not _diag_ok():
        return jsonify({"error": "Unauthorized"}), 401
    import urllib.request as _u
    defs = [
        ("attendance", os.environ.get("TELEGRAM_ATTENDANCE_BOT_TOKEN", ""),
         "الحضور والانصراف: تسجيل حضور/انصراف بالموقع (geofence)، الحالة اليومية، الغياب، تسجيل موظف جديد وموافقة المدير."),
        ("tasks", os.environ.get("TELEGRAM_TASKS_BOT_TOKEN", ""),
         "المهام: يبعت للموظف مهامه ولينك البوابة وبياناته، وتذكير يومي بالتاسكات اللي عليه دورها، وإشعارات التسليم/المراجعة."),
    ]
    out = []
    for role, tok, desc in defs:
        info = {"role": role, "configured": bool(tok), "description": desc}
        if tok:
            try:
                r = json.loads(_u.urlopen(f"https://api.telegram.org/bot{tok}/getMe", timeout=10).read())
                me = r.get("result", {})
                info["username"] = "@" + me.get("username", "") if me.get("username") else ""
                info["name"] = me.get("first_name", "")
                info["id"] = me.get("id")
                # webhook status
                w = json.loads(_u.urlopen(f"https://api.telegram.org/bot{tok}/getWebhookInfo", timeout=10).read()).get("result", {})
                info["webhook"] = w.get("url", "") or "(polling / none)"
            except Exception as e:
                info["error"] = str(e)[:120]
        out.append(info)
    return jsonify({"bots": out})


@app.route("/api/drive/diag", methods=["GET"])
def drive_diag():
    """Verify Google Drive is fully wired: OAuth token, folder create, file upload
    (link-readable), and cleanup. Auth: admin session OR ?key=CRON_SECRET."""
    if not _diag_ok():
        return jsonify({"error": "Unauthorized"}), 401
    out = {"token": False, "upload": False, "link": "", "public": False, "folder": False, "cleanup": False}
    token = get_google_oauth_access_token()
    out["token"] = bool(token)
    if not token:
        out["hint"] = "GOOGLE_* env not set or refresh token invalid"
        return jsonify(out)
    # 1) upload a tiny text file
    link = drive_upload_bytes("domya_drive_healthcheck.txt", b"ok", "text/plain")
    out["upload"] = bool(link)
    out["link"] = link or ""
    fid = drive_file_id(link) if link else ""
    # 2) verify it is readable via the public link (anyone-with-link)
    if link:
        try:
            import urllib.request as _u
            code = _u.urlopen(f"https://drive.google.com/uc?export=download&id={fid}", timeout=15).getcode()
            out["public"] = (code == 200)
        except Exception as e:
            out["public_err"] = str(e)[:120]
    # 3) folder create
    folder = create_google_drive_client_folder("Domya — Health Check")
    out["folder"] = bool(folder)
    out["folder_link"] = folder or ""
    # 4) cleanup both test items
    for _id in [fid, drive_file_id(folder) if folder else ""]:
        if not _id:
            continue
        try:
            req = urllib.request.Request(f"https://www.googleapis.com/drive/v3/files/{_id}",
                                         headers={"Authorization": f"Bearer {token}"}, method="DELETE")
            urllib.request.urlopen(req, timeout=15).read()
            out["cleanup"] = True
        except Exception as e:
            out["cleanup_err"] = str(e)[:120]
    out["ready"] = bool(out["token"] and out["upload"] and out["public"])
    return jsonify(out)


@app.route("/api/telegram/attendance/setup", methods=["POST", "GET"])
def telegram_attendance_setup():
    """Register (or delete) the attendance bot webhook to point at THIS app.
    Auth: admin session OR ?key=CRON_SECRET. ?action=delete restores n8n polling."""
    if not _diag_ok():
        return jsonify({"error": "Unauthorized"}), 401
    tok = _att_bot_token()
    if not tok:
        return jsonify({"error": "attendance bot token not set"}), 400
    action = request.args.get("action", "set")
    try:
        if action == "delete":
            r = _urlreq.urlopen(f"https://api.telegram.org/bot{tok}/deleteWebhook?drop_pending_updates=false", timeout=12).read()
            return jsonify({"ok": True, "action": "deleted", "result": json.loads(r)})
        base = os.environ.get("PORTAL_URL", "https://metaaimoderator.vercel.app").rstrip("/")
        hook = f"{base}/api/telegram/attendance"
        payload = {"url": hook, "allowed_updates": ["message", "edited_message", "callback_query"]}
        sec = os.environ.get("TELEGRAM_WEBHOOK_SECRET", "")
        if sec:
            payload["secret_token"] = sec
        req = _urlreq.Request(f"https://api.telegram.org/bot{tok}/setWebhook",
                              data=json.dumps(payload).encode("utf-8"),
                              headers={"Content-Type": "application/json"})
        res = json.loads(_urlreq.urlopen(req, timeout=12).read())
        return jsonify({"ok": res.get("ok", False), "webhook": hook, "result": res})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 500


